insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c9000000-0000-0000-0000-000000000001', 'ukmla', '1721554b-3911-4ef1-930a-66ee8306d7da',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c9000000-0000-0000-0000-000000000001', 'A', 'Reassure the family that urinary incontinence is a normal part of ageing and no investigation is needed', false, 'Ruled out because new-onset incontinence with fever and confusion is not simply age-related change; it signals an acute illness (likely UTI) that requires investigation and treatment.', 1),
('c9000000-0000-0000-0000-000000000001', 'B', 'Start an antimuscarinic bladder-stabilising drug for overactive bladder', false, 'Ruled out because antimuscarinics do not treat the underlying infection, worsen confusion, and are inappropriate when an acute UTI has not yet been treated.', 2),
('c9000000-0000-0000-0000-000000000001', 'C', 'Insert a long-term indwelling urinary catheter to manage the incontinence', false, 'Ruled out because catheterisation is not first-line for urge incontinence, introduces infection risk, and does not address the underlying UTI causing her symptoms.', 3),
('c9000000-0000-0000-0000-000000000001', 'D', 'Send a midstream urine sample for culture and start empirical antibiotics for a symptomatic urinary tract infection', true, 'Correct. New urinary symptoms with fever, leucocytes and nitrites on urinalysis, plus new confusion, are consistent with a symptomatic UTI precipitating delirium in an older adult; a culture should be sent and empirical antibiotics started per local guidance while awaiting results.', 4),
('c9000000-0000-0000-0000-000000000001', 'E', 'Arrange an outpatient urology referral for further assessment in six weeks', false, 'Ruled out because this delays treatment of a likely acute infection causing delirium, which needs same-day assessment and treatment, not deferred outpatient review.', 5),
('c9000000-0000-0000-0000-000000000002', 'A', 'Start an alpha-blocker and review in the community in one week', false, 'Ruled out because alpha-blockers may aid future voiding trials but do not relieve an acute, painful retention that needs immediate bladder decompression.', 1),
('c9000000-0000-0000-0000-000000000002', 'B', 'Arrange an urgent outpatient ultrasound of the renal tract before any intervention', false, 'Ruled out because imaging should not delay decompression of a painful, distended bladder; catheterisation is the immediate priority, with imaging arranged afterwards if indicated.', 2),
('c9000000-0000-0000-0000-000000000002', 'C', 'Encourage oral fluids and reassess for spontaneous voiding in 24 hours', false, 'Ruled out because acute retention with a palpable bladder will not resolve spontaneously and risks bladder injury, renal impairment and worsening pain if untreated.', 3),
('c9000000-0000-0000-0000-000000000002', 'D', 'Perform a suprapubic aspiration as first-line treatment', false, 'Ruled out because urethral catheterisation is the first-line approach; suprapubic aspiration or catheter is reserved for cases where urethral catheterisation fails or is contraindicated.', 4),
('c9000000-0000-0000-0000-000000000002', 'E', 'Immediate urethral catheterisation to relieve the retention', true, 'Correct. Acute urinary retention with a large, tender, palpable bladder requires immediate catheterisation to relieve pain and prevent renal impairment; the volume and timing should be documented and post-obstructive diuresis monitored.', 5),
('c9000000-0000-0000-0000-000000000003', 'A', 'New-onset infective diarrhoea requiring stool culture and isolation', false, 'Ruled out because the clinical picture (rectal impaction, chronic constipation, opioid use) points to overflow incontinence from impaction rather than an infective cause, although infection should still be excluded if clinically suspected.', 1),
('c9000000-0000-0000-0000-000000000003', 'B', 'Faecal impaction causing overflow (spurious) diarrhoea', true, 'Correct. Hard impacted stool in the rectum with liquid stool leaking around it produces overflow incontinence, often misinterpreted as diarrhoea; opioids such as codeine are a common contributing cause in older patients.', 2),
('c9000000-0000-0000-0000-000000000003', 'C', 'Irritable bowel syndrome with diarrhoea-predominant symptoms', false, 'Ruled out because irritable bowel syndrome is a diagnosis of exclusion in younger patients and does not explain a palpable faecal mass and rectal impaction in this context.', 3),
('c9000000-0000-0000-0000-000000000003', 'D', 'Colorectal malignancy causing tenesmus and mucous discharge', false, 'Ruled out as the primary explanation here because the findings are best explained by faecal impaction from opioid-induced constipation, though malignancy should remain a consideration if symptoms persist after disimpaction.', 4),
('c9000000-0000-0000-0000-000000000003', 'E', 'Normal age-related bowel incontinence requiring only containment pads', false, 'Ruled out because faecal incontinence is not a normal part of ageing and always warrants assessment for a reversible cause such as impaction.', 5),
('c9000000-0000-0000-0000-000000000004', 'A', 'Discharge home immediately since she was independent before admission', false, 'Ruled out because current functional status, not premorbid status, determines safety to return home; discharging without assessment risks a fall or failed discharge.', 1),
('c9000000-0000-0000-0000-000000000004', 'B', 'Arrange permanent placement in a nursing home without further assessment', false, 'Ruled out because a placement decision should not be made prematurely; many patients regain function with rehabilitation and a formal assessment is needed first.', 2),
('c9000000-0000-0000-0000-000000000004', 'C', 'Refer for physiotherapy and occupational therapy assessment of mobility, transfers and home safety before planning discharge', true, 'Correct. Functional decline during hospitalisation (deconditioning) is common in older adults and requires formal multidisciplinary assessment of mobility, transfers and home environment before a safe discharge plan can be made, rather than discharging based on premorbid function alone.', 3),
('c9000000-0000-0000-0000-000000000004', 'D', 'Discharge with no follow-up as the chest infection has been treated', false, 'Ruled out because treating the acute infection does not address her new functional impairment, which needs specific assessment and support.', 4),
('c9000000-0000-0000-0000-000000000004', 'E', 'Request an urgent CT head to investigate the reduced mobility', false, 'Ruled out because there are no focal neurological findings suggesting a new intracranial cause; the presentation is consistent with deconditioning after acute illness, not a neurological event.', 5),
('c9000000-0000-0000-0000-000000000005', 'A', 'Oxybutynin has high anticholinergic activity and can worsen cognition and cause confusion in patients with cognitive impairment; a bladder-selective agent with lower anticholinergic burden (or a beta-3 agonist such as mirabegron) should be considered instead', true, 'Correct. Oxybutynin crosses the blood-brain barrier and has a high anticholinergic burden, increasing the risk of worsening cognitive impairment, confusion and falls in older or cognitively impaired patients; alternatives with lower central anticholinergic effect are preferred.', 1),
('c9000000-0000-0000-0000-000000000005', 'B', 'Oxybutynin is safe and should be started at the maximum dose immediately for rapid symptom control', false, 'Ruled out because starting at a high dose increases the risk of anticholinergic side effects and confusion; even if used, a low starting dose with monitoring would be appropriate, but a lower-burden alternative is preferable here.', 2),
('c9000000-0000-0000-0000-000000000005', 'C', 'No further action is needed since bladder training has already been trialled', false, 'Ruled out because if conservative measures fail, safe pharmacological options should still be considered, with careful attention to anticholinergic burden given her cognitive impairment.', 3),
('c9000000-0000-0000-0000-000000000005', 'D', 'A long-term indwelling catheter should be inserted instead of any medication trial', false, 'Ruled out because catheterisation carries infection and other risks and is not first-line for urge incontinence when other options have not been fully explored.', 4),
('c9000000-0000-0000-0000-000000000005', 'E', 'Referral for urgent cystoscopy is required before any further management', false, 'Ruled out because cystoscopy is not indicated for typical urge incontinence without red flag features such as haematuria; it is not the next step here.', 5),
('c9000000-0000-0000-0000-000000000006', 'A', 'Start a course of oral antibiotics based on the urinalysis result', false, 'Ruled out because treating asymptomatic bacteriuria does not improve outcomes, promotes resistance, and is not recommended in catheterised patients without systemic symptoms.', 1),
('c9000000-0000-0000-0000-000000000006', 'B', 'Change the catheter and start prophylactic antibiotics for one week', false, 'Ruled out because routine antibiotic prophylaxis at catheter change is not recommended and catheter change alone is not indicated based on urinalysis findings without symptoms.', 2),
('c9000000-0000-0000-0000-000000000006', 'C', 'Admit for intravenous antibiotics given the abnormal urinalysis', false, 'Ruled out because admission and intravenous antibiotics are unnecessary in an asymptomatic, systemically well patient; this would be appropriate only with signs of systemic infection.', 3),
('c9000000-0000-0000-0000-000000000006', 'D', 'Remove the catheter immediately and arrange intermittent self-catheterisation', false, 'Ruled out because the underlying indication for the catheter (chronic retention) has not changed; catheter removal should be planned based on clinical need, not an incidental urinalysis result.', 4),
('c9000000-0000-0000-0000-000000000006', 'E', 'No antibiotic treatment is required, as asymptomatic bacteriuria in a catheterised patient should not be treated', true, 'Correct. Bacteriuria is almost universal in long-term catheterised patients and urine will often appear cloudy or test positive on urinalysis; without systemic symptoms such as fever, rigors or new confusion, treatment is not indicated and risks promoting antimicrobial resistance.', 5),
('c9000000-0000-0000-0000-000000000007', 'A', 'Implement a structured repositioning schedule and use a pressure-redistributing mattress', true, 'Correct. Regular repositioning combined with an appropriate pressure-redistributing surface is the cornerstone of pressure ulcer prevention in immobile, high-risk patients, alongside optimising nutrition and skin care.', 1),
('c9000000-0000-0000-0000-000000000007', 'B', 'Apply a barrier cream to the sacrum only if skin breakdown occurs', false, 'Ruled out because prevention should be proactive in a high-risk patient, not reactive after skin breakdown has already begun.', 2),
('c9000000-0000-0000-0000-000000000007', 'C', 'Delay any preventive measures until after surgical fixation of the fracture', false, 'Ruled out because pressure ulcer risk begins as soon as mobility is reduced; preventive measures should start immediately regardless of surgical timing.', 3),
('c9000000-0000-0000-0000-000000000007', 'D', 'Restrict oral fluids to reduce moisture-associated skin damage', false, 'Ruled out because restricting fluids does not prevent pressure ulcers and risks dehydration; adequate hydration and nutrition support skin integrity.', 4),
('c9000000-0000-0000-0000-000000000007', 'E', 'Reassess pressure ulcer risk only if she develops visible skin changes', false, 'Ruled out because risk assessment and preventive action should occur before skin changes develop, not be triggered only once damage is visible.', 5),
('c9000000-0000-0000-0000-000000000008', 'A', 'Normal progression of dementia causing loss of bladder control', false, 'Ruled out because a new, acute change in continence with a large bladder residual points to a specific reversible precipitant (retention/constipation) rather than simply attributing it to dementia progression.', 1),
('c9000000-0000-0000-0000-000000000008', 'B', 'Chronic urinary retention with overflow incontinence, likely exacerbated by faecal loading', true, 'Correct. A large post-void residual with suprapubic fullness indicates retention with overflow incontinence; significant constipation is a common precipitant or aggravating factor in older adults and should be assessed and treated alongside bladder management.', 2),
('c9000000-0000-0000-0000-000000000008', 'C', 'Urge incontinence due to an overactive bladder requiring antimuscarinic therapy', false, 'Ruled out because the large residual volume indicates retention with overflow, not an overactive bladder; antimuscarinics would worsen retention in this context.', 3),
('c9000000-0000-0000-0000-000000000008', 'D', 'Psychogenic incontinence related to his agitation', false, 'Ruled out because there is an identifiable physical cause (retention and constipation) that should be addressed rather than attributing symptoms to behavioural factors alone.', 4),
('c9000000-0000-0000-0000-000000000008', 'E', 'Diabetic autonomic neuropathy causing bladder dysfunction', false, 'Ruled out as there is no mention of diabetes, and the acute two-day change with faecal loading better explains the presentation than a chronic neuropathic process.', 5),
('c9000000-0000-0000-0000-000000000009', 'A', 'Urge incontinence due to detrusor overactivity', false, 'Ruled out because urge incontinence is characterised by a sudden compelling urge to void followed by leakage, not leakage triggered by physical exertion without urgency.', 1),
('c9000000-0000-0000-0000-000000000009', 'B', 'Overflow incontinence secondary to chronic retention', false, 'Ruled out because there is no history suggesting incomplete bladder emptying or a palpable bladder, and leakage is specifically related to exertion rather than continuous dribbling.', 2),
('c9000000-0000-0000-0000-000000000009', 'C', 'Functional incontinence due to immobility', false, 'Ruled out because there is no indication of impaired mobility or cognition limiting access to the toilet; the leakage pattern is specifically related to raised abdominal pressure.', 3),
('c9000000-0000-0000-0000-000000000009', 'D', 'Stress urinary incontinence', true, 'Correct. Leakage precipitated by raised intra-abdominal pressure (coughing, laughing, lifting) without preceding urgency is characteristic of stress incontinence, commonly related to pelvic floor weakness after vaginal deliveries.', 4),
('c9000000-0000-0000-0000-000000000009', 'E', 'Urinary tract infection', false, 'Ruled out because urinalysis is negative and there are no symptoms of infection such as dysuria or fever.', 5),
('c9000000-0000-0000-0000-000000000010', 'A', 'Discharge him home today with a walking stick as previously used', false, 'Ruled out because his current mobility has not been shown to be safe for his home environment (stairs, no support); discharging without assessment risks a fall or readmission.', 1),
('c9000000-0000-0000-0000-000000000010', 'B', 'Transfer him directly to a nursing home placement without further assessment', false, 'Ruled out because premature placement decisions should be avoided; his rehabilitation potential and home suitability have not yet been fully assessed.', 2),
('c9000000-0000-0000-0000-000000000010', 'C', 'Arrange occupational therapy assessment including a stair and home assessment before discharge is finalised', true, 'Correct. Given his residual mobility deficit, lack of on-site support, and stairs at home, a formal occupational therapy assessment (including stair negotiation and consideration of a home visit) is essential before a safe discharge plan can be agreed.', 3),
('c9000000-0000-0000-0000-000000000010', 'D', 'Discharge with a referral to his GP for review within two weeks', false, 'Ruled out because this does not address the immediate safety concern of returning to a first-floor flat with impaired mobility and no support before discharge.', 4),
('c9000000-0000-0000-0000-000000000010', 'E', 'Keep him in hospital indefinitely until his mobility returns fully to baseline', false, 'Ruled out because prolonged hospital stay itself risks further deconditioning; the appropriate step is targeted assessment and rehabilitation planning, not indefinite admission.', 5),
('c9000000-0000-0000-0000-000000000011', 'A', 'Mini-Mental State Examination to formally diagnose dementia', false, 'Ruled out because a formal cognitive test for dementia is not appropriate during an acute, fluctuating presentation; delirium must be excluded/identified first, and cognitive testing is unreliable during an acute confusional state.', 1),
('c9000000-0000-0000-0000-000000000011', 'B', 'Glasgow Coma Scale alone to assess conscious level', false, 'Ruled out because while GCS documents conscious level, it does not screen for delirium features such as inattention, disorientation, or acute fluctuation and is insufficient alone.', 2),
('c9000000-0000-0000-0000-000000000011', 'C', 'Waterlow score to assess pressure ulcer risk', false, 'Ruled out because this tool assesses skin breakdown risk, not cognitive or attentional change, and is not relevant to this presentation.', 3),
('c9000000-0000-0000-0000-000000000011', 'D', '4AT rapid delirium screening tool', true, 'Correct. The 4AT is a quick, validated bedside tool used to screen for delirium, assessing alertness, orientation, attention (months backwards) and acute change/fluctuation; it is appropriate for this acute change in a post-operative older patient, including hypoactive presentations.', 4),
('c9000000-0000-0000-0000-000000000011', 'E', 'Barthel Index to assess activities of daily living', false, 'Ruled out because this measures functional independence, not acute cognitive change, and would not identify or characterise delirium.', 5),
('c9000000-0000-0000-0000-000000000012', 'A', 'Impaired short-term memory on cognitive testing', false, 'Ruled out because memory impairment can occur in both delirium and dementia and does not by itself distinguish between the two conditions.', 1),
('c9000000-0000-0000-0000-000000000012', 'B', 'Acute onset over 24 hours with a fluctuating course', true, 'Correct. Delirium characteristically develops acutely (hours to days) and fluctuates in severity, often worse at night, whereas dementia has an insidious onset over months to years with a more stable, gradually progressive course.', 2),
('c9000000-0000-0000-0000-000000000012', 'C', 'Age over 75 years', false, 'Ruled out because age alone does not differentiate delirium from dementia; both are more common with advancing age but this is not a discriminating clinical feature.', 3),
('c9000000-0000-0000-0000-000000000012', 'D', 'Presence of a background medical condition such as diabetes', false, 'Ruled out because having a chronic medical condition does not distinguish delirium from dementia; it may be a risk factor for either but is not diagnostic.', 4),
('c9000000-0000-0000-0000-000000000012', 'E', 'Difficulty naming objects on examination', false, 'Ruled out because dysphasia/anomia can occur in both delirium and dementia and is not a specific discriminating feature between the two.', 5),
('c9000000-0000-0000-0000-000000000013', 'A', $x$Alzheimer's disease$x$, true, $x$Correct. Insidious, progressive memory-predominant decline with early impairment of episodic memory and visuospatial/executive function, alongside hippocampal-predominant atrophy on imaging, is the classic pattern of Alzheimer's disease, the most common cause of dementia.$x$, 1),
('c9000000-0000-0000-0000-000000000013', 'B', 'Vascular dementia', false, 'Ruled out because vascular dementia typically presents with a stepwise decline associated with vascular risk factors or stroke events, and imaging usually shows significant cerebrovascular disease rather than isolated hippocampal atrophy.', 2),
('c9000000-0000-0000-0000-000000000013', 'C', 'Dementia with Lewy bodies', false, 'Ruled out because Lewy body dementia typically features fluctuating cognition, visual hallucinations and parkinsonism early in the disease course, none of which are described here.', 3),
('c9000000-0000-0000-0000-000000000013', 'D', 'Frontotemporal dementia', false, 'Ruled out because frontotemporal dementia usually presents with early personality and behavioural change or language difficulty, with relative preservation of memory early on; this patient has a memory-predominant picture with unchanged personality.', 4),
('c9000000-0000-0000-0000-000000000013', 'E', 'Normal pressure hydrocephalus', false, 'Ruled out because normal pressure hydrocephalus classically presents with the triad of gait disturbance, urinary incontinence and cognitive decline, with ventriculomegaly on imaging, not isolated progressive memory loss.', 5),
('c9000000-0000-0000-0000-000000000014', 'A', 'Administer haloperidol as first-line treatment and withhold thiamine until oral intake resumes', false, $x$Ruled out because benzodiazepines, not antipsychotics, are first-line for alcohol withdrawal/delirium tremens, and thiamine should be given promptly (ideally before glucose) rather than delayed, to prevent Wernicke's encephalopathy.$x$, 1),
('c9000000-0000-0000-0000-000000000014', 'B', 'Reassure the patient that this is a normal post-operative reaction and continue to observe without treatment', false, 'Ruled out because delirium tremens is a medical emergency with significant morbidity and mortality if untreated, requiring urgent pharmacological management, not observation alone.', 2),
('c9000000-0000-0000-0000-000000000014', 'C', 'Urgent treatment with a reducing regimen of benzodiazepines (e.g. chlordiazepoxide) and intravenous thiamine', true, $x$Correct. This presentation with tremor, autonomic hyperactivity, agitation and visual hallucinations three days after stopping alcohol is consistent with delirium tremens, a medical emergency requiring prompt benzodiazepine treatment and thiamine replacement to prevent Wernicke's encephalopathy.$x$, 3),
('c9000000-0000-0000-0000-000000000014', 'D', 'Start intravenous glucose immediately without thiamine', false, $x$Ruled out because giving glucose without prior or concurrent thiamine in a potentially thiamine-deficient patient risks precipitating Wernicke's encephalopathy.$x$, 4),
('c9000000-0000-0000-0000-000000000014', 'E', 'Discharge home with outpatient alcohol services follow-up', false, 'Ruled out because delirium tremens with autonomic instability requires inpatient monitoring and urgent treatment, not discharge.', 5),
('c9000000-0000-0000-0000-000000000015', 'A', 'Start regular high-dose antipsychotic medication as first-line management of her agitation', false, 'Ruled out because antipsychotics are not first-line for behavioural symptoms in dementia and carry significant risks (stroke, mortality) in this population; high-dose regular use is not appropriate.', 1),
('c9000000-0000-0000-0000-000000000015', 'B', 'Physically restrain her in bed using bedrails and limb restraints to prevent falls', false, 'Ruled out because physical restraint increases agitation, distress and injury risk and is not an appropriate or recommended management strategy.', 2),
('c9000000-0000-0000-0000-000000000015', 'C', 'Sedate her with a benzodiazepine as first-line treatment', false, 'Ruled out because benzodiazepines can worsen confusion and increase falls risk in older patients with dementia and are not first-line for this indication.', 3),
('c9000000-0000-0000-0000-000000000015', 'D', 'Discharge her immediately to avoid further hospital-associated agitation', false, 'Ruled out because discharging an agitated, at-risk patient without addressing safety and the underlying cause of admission is inappropriate and unsafe.', 4),
('c9000000-0000-0000-0000-000000000015', 'E', 'Consider a low-dose, short-term antipsychotic such as haloperidol only if non-pharmacological measures have failed and there is a genuine safety risk, after excluding Lewy body dementia or Parkinsonian features', true, 'Correct. Pharmacological treatment for agitation in dementia should be reserved for situations where non-pharmacological measures have failed and there is significant risk of harm; a low-dose, short-term antipsychotic may be considered, but Lewy body dementia and parkinsonism must first be excluded due to severe neuroleptic sensitivity.', 5),
('c9000000-0000-0000-0000-000000000016', 'A', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease typically presents with progressive memory loss rather than prominent fluctuating cognition, early visual hallucinations and parkinsonism.$x$, 1),
('c9000000-0000-0000-0000-000000000016', 'B', $x$Parkinson's disease without cognitive impairment$x$, false, $x$Ruled out because the prominent early fluctuating cognitive impairment and visual hallucinations, alongside motor features, favour dementia with Lewy bodies rather than motor-only Parkinson's disease.$x$, 2),
('c9000000-0000-0000-0000-000000000016', 'C', 'Dementia with Lewy bodies', true, 'Correct. The combination of fluctuating cognition, recurrent visual hallucinations, spontaneous parkinsonism, and marked sensitivity to antipsychotic medication is the classic clinical picture of dementia with Lewy bodies.', 3),
('c9000000-0000-0000-0000-000000000016', 'D', 'Vascular dementia', false, 'Ruled out because vascular dementia usually shows a stepwise decline linked to vascular events, not the fluctuating cognition, hallucinations and neuroleptic sensitivity seen here.', 4),
('c9000000-0000-0000-0000-000000000016', 'E', 'Delirium secondary to an acute infection', false, 'Ruled out because the history describes a chronic pattern over several months with characteristic features of a neurodegenerative disease, rather than an acute, reversible confusional state.', 5),
('c9000000-0000-0000-0000-000000000017', 'A', 'Assume this represents natural progression of her underlying dementia and make no further changes', false, 'Ruled out because an acute two-day change in cognition should never be attributed solely to dementia progression without excluding reversible causes such as infection.', 1),
('c9000000-0000-0000-0000-000000000017', 'B', 'Start an antipsychotic immediately to control her agitation before any other assessment', false, 'Ruled out because the priority is identifying and treating the underlying cause of delirium; antipsychotics are not first-line and should only be considered after non-pharmacological measures fail and safety is a concern.', 2),
('c9000000-0000-0000-0000-000000000017', 'C', 'Treat with broad-spectrum intravenous antibiotics without sending any cultures', false, 'Ruled out because cultures should be sent before starting antibiotics where possible to guide appropriate treatment and avoid unnecessary broad-spectrum use.', 3),
('c9000000-0000-0000-0000-000000000017', 'D', 'Discharge her back to her care home with no further assessment since she is not septic', false, 'Ruled out because new delirium requires assessment and a management plan even in the absence of sepsis, as there is a treatable urinary source and other precipitants to consider.', 4),
('c9000000-0000-0000-0000-000000000017', 'E', 'Assess for and treat likely reversible precipitants of delirium, including sending a urine culture and considering antibiotics if clinically indicated, alongside a full delirium screen (infection, drugs, metabolic causes, constipation, pain)', true, 'Correct. New confusion in an older patient with dementia should trigger a systematic search for reversible precipitants of delirium; urinary symptoms with a positive urinalysis support likely UTI as a contributing cause, but a broader screen (medication review, hydration, constipation, pain, other infection sources) should also be performed.', 5),
('c9000000-0000-0000-0000-000000000018', 'A', 'Respect her refusal automatically since all patients have an absolute right to refuse treatment', false, $x$Ruled out because the right to refuse treatment applies to patients with capacity for that decision; where capacity is lacking, decisions must be made in the patient's best interests rather than accepting the refusal at face value.$x$, 1),
('c9000000-0000-0000-0000-000000000018', 'B', 'Assume she lacks capacity for all decisions because she has a diagnosis of dementia', false, 'Ruled out because a diagnosis of dementia does not automatically mean a patient lacks capacity; capacity must be assessed for the specific decision at the specific time.', 2),
('c9000000-0000-0000-0000-000000000018', 'C', 'Give the antibiotics covertly without further discussion or assessment', false, 'Ruled out because treatment decisions, especially where capacity is in question, require proper capacity assessment and, where relevant, best-interests decision-making with appropriate documentation, not covert administration without assessment.', 3),
('c9000000-0000-0000-0000-000000000018', 'D', 'Assess her mental capacity specifically in relation to this treatment decision and, if she lacks capacity, make a best-interests decision involving family and the clinical team', true, 'Correct. Capacity is decision-specific and time-specific; her inability to understand, retain or weigh the relevant information suggests she may lack capacity for this particular decision, in which case a best-interests decision should be made in line with mental capacity legislation, involving family and the wider team where possible.', 4),
('c9000000-0000-0000-0000-000000000018', 'E', 'Ask her family to make the final decision on her behalf regardless of her own capacity assessment', false, 'Ruled out because a formal capacity assessment for the specific decision must be performed first; family input is part of best-interests decision-making, but does not replace the need for that assessment.', 5),
('c9000000-0000-0000-0000-000000000019', 'A', 'Routine prophylactic low-dose antipsychotic medication for all high-risk patients on admission', false, 'Ruled out because prophylactic antipsychotics are not recommended for delirium prevention and carry unnecessary risk without proven benefit in this context.', 1),
('c9000000-0000-0000-0000-000000000019', 'B', 'A multicomponent intervention addressing orientation, hydration, mobilisation, sensory impairment (glasses/hearing aids), sleep hygiene and medication review', true, 'Correct. Multicomponent, non-pharmacological interventions that simultaneously address several modifiable risk factors (cognitive orientation, hydration, early mobilisation, correcting sensory impairment, promoting normal sleep-wake cycles, and reviewing deliriogenic medications) have the strongest evidence for reducing delirium incidence in hospitalised older adults.', 2),
('c9000000-0000-0000-0000-000000000019', 'C', 'Routine use of physical restraints for all patients identified as high risk', false, 'Ruled out because restraints increase agitation and the risk of injury and are not an evidence-based preventive strategy; they may worsen, rather than prevent, delirium.', 3),
('c9000000-0000-0000-0000-000000000019', 'D', 'Prescribing a benzodiazepine at night to all high-risk patients to improve sleep', false, 'Ruled out because benzodiazepines are themselves a risk factor for delirium in older adults and are not an appropriate preventive measure.', 4),
('c9000000-0000-0000-0000-000000000019', 'E', 'Nil by mouth after midday for all high-risk patients to reduce aspiration risk', false, 'Ruled out because unnecessary fasting promotes dehydration, a known risk factor for delirium, and is not an appropriate blanket preventive strategy.', 5),
('c9000000-0000-0000-0000-000000000020', 'A', 'Depression presenting with cognitive impairment (pseudodementia)', true, $x$Correct. A relatively rapid onset of cognitive complaints in the context of clear depressive symptoms, recent bereavement, and a pattern of poor effort with 'don't know' answers that improve with prompting, is characteristic of depression-related cognitive impairment rather than a primary dementia.$x$, 1),
('c9000000-0000-0000-0000-000000000020', 'B', $x$Early Alzheimer's disease$x$, false, $x$Ruled out because the abrupt onset linked to bereavement, prominent mood symptoms, and inconsistent effort on testing (improving with encouragement) are more typical of depression than the insidious, effort-independent decline of Alzheimer's disease.$x$, 2),
('c9000000-0000-0000-0000-000000000020', 'C', 'Vascular dementia', false, 'Ruled out because there is no history of vascular risk factors or stepwise decline described; the clinical picture is better explained by a depressive episode.', 3),
('c9000000-0000-0000-0000-000000000020', 'D', 'Normal age-related cognitive decline', false, 'Ruled out because her symptoms are associated with clear depressive features and functional impact, which is not consistent with benign age-related change alone.', 4),
('c9000000-0000-0000-0000-000000000020', 'E', 'Delirium secondary to an underlying infection', false, 'Ruled out because there is no acute fluctuating confusional state or evidence of an acute physical illness; the three-month timescale and mood symptoms point to depression rather than delirium.', 5),
('c9000000-0000-0000-0000-000000000021', 'A', 'Vestibular neuritis causing sudden vertigo', false, 'Ruled out because her symptoms are specifically related to standing up (postural change) with a demonstrated significant blood pressure drop, rather than the sustained vertigo independent of posture seen in vestibular neuritis.', 1),
('c9000000-0000-0000-0000-000000000021', 'B', 'Cardiac arrhythmia unrelated to posture', false, 'Ruled out because her symptoms are clearly triggered by postural change and correlate with a measured orthostatic blood pressure drop, making this the most likely explanation over an unwitnessed arrhythmia, although cardiac causes should still be considered if this does not fully explain her falls.', 2),
('c9000000-0000-0000-0000-000000000021', 'C', 'Peripheral neuropathy causing loss of proprioception', false, 'Ruled out because there is no mention of sensory symptoms or gait disturbance suggesting neuropathy; the clear postural blood pressure drop better explains the fall.', 3),
('c9000000-0000-0000-0000-000000000021', 'D', 'Hypoglycaemia related to diabetes medication', false, 'Ruled out because there is no history of diabetes or hypoglycaemic symptoms described, and the confirmed orthostatic drop in blood pressure is the more likely explanation.', 4),
('c9000000-0000-0000-0000-000000000021', 'E', 'Orthostatic (postural) hypotension, likely exacerbated by her antihypertensive medications', true, 'Correct. A drop in systolic blood pressure of more than 20 mmHg (or diastolic more than 10 mmHg) on standing, with symptoms of dizziness, confirms orthostatic hypotension; antihypertensive medications such as thiazide diuretics and calcium channel blockers are common contributing causes in older adults.', 5),
('c9000000-0000-0000-0000-000000000022', 'A', 'Discharge home with no further action since he was not injured this time', false, 'Ruled out because recurrent falls are a marker of underlying risk and warrant assessment even without injury, to prevent future, potentially more serious falls.', 1),
('c9000000-0000-0000-0000-000000000022', 'B', 'Perform a multifactorial falls risk assessment, including gait and balance, vision, cognition, cardiovascular assessment and medication review', true, 'Correct. Recurrent falls in an older adult warrant a comprehensive multifactorial assessment addressing the range of contributing factors (gait/balance, vision, cardiovascular causes, cognition, environment, and medications), as recommended for anyone presenting with recurrent falls or a single injurious fall.', 2),
('c9000000-0000-0000-0000-000000000022', 'C', 'Arrange an urgent CT head as the only necessary investigation', false, 'Ruled out because CT head is not routinely required for an unwitnessed fall without head injury or neurological signs; a broader multifactorial assessment is needed instead.', 3),
('c9000000-0000-0000-0000-000000000022', 'D', 'Refer directly for permanent residential care placement', false, 'Ruled out because this is premature without first assessing and addressing modifiable risk factors, which may allow him to remain safely at home with support.', 4),
('c9000000-0000-0000-0000-000000000022', 'E', 'Prescribe a hip protector and take no further action', false, 'Ruled out because hip protectors alone do not address the underlying causes of recurrent falls and are not a substitute for a comprehensive assessment.', 5),
('c9000000-0000-0000-0000-000000000023', 'A', 'Frailty syndrome', true, 'Correct. Unintentional weight loss, exhaustion, slow gait speed, weak grip strength and low physical activity are the five components of the frailty phenotype; meeting three or more of these criteria defines frailty, a state of increased vulnerability to adverse outcomes including falls.', 1),
('c9000000-0000-0000-0000-000000000023', 'B', 'Normal healthy ageing', false, 'Ruled out because this constellation of features (weight loss, exhaustion, weakness, slow gait, low activity) represents a recognised pathological syndrome (frailty) associated with increased risk of adverse outcomes, not simply expected ageing.', 2),
('c9000000-0000-0000-0000-000000000023', 'C', 'Major depressive disorder', false, 'Ruled out because although fatigue can occur in depression, the specific combination of weight loss, slow gait speed and reduced grip strength is characteristic of the physical frailty phenotype rather than depression alone; mood should still be assessed as a contributing factor.', 3),
('c9000000-0000-0000-0000-000000000023', 'D', 'Hyperthyroidism', false, 'Ruled out because although hyperthyroidism can cause weight loss, it typically presents with additional features such as tachycardia, tremor and heat intolerance, and does not typically cause slow gait or reduced grip strength as part of a frailty phenotype.', 4),
('c9000000-0000-0000-0000-000000000023', 'E', 'Malignancy as the primary and only explanation', false, 'Ruled out because while malignancy should be considered and excluded as a cause of weight loss, the described combination of features specifically fits the recognised frailty phenotype, and this diagnosis should not be assumed without appropriate assessment.', 5),
('c9000000-0000-0000-0000-000000000024', 'A', 'Continue all current medications unchanged and simply increase nursing supervision', false, 'Ruled out because increased supervision alone does not address the modifiable pharmacological contributors to his falls risk, which should be actively reviewed and reduced where possible.', 1),
('c9000000-0000-0000-0000-000000000024', 'B', 'Start a new antipsychotic to sedate him at night to prevent him getting out of bed unsupervised', false, 'Ruled out because adding a further sedating medication would increase, not decrease, his falls risk, and does not address the underlying issue.', 2),
('c9000000-0000-0000-0000-000000000024', 'C', 'Review and rationalise his medications, focusing on stopping or reducing drugs that increase falls risk such as the sedative-hypnotic and the antihypertensive combination', true, 'Correct. Multiple medications with sedative, hypotensive or anticholinergic properties (zopiclone, amitriptyline, and the combination of two antihypertensives) significantly increase falls risk in older adults; a structured medication review to stop or reduce unnecessary or high-risk drugs is the most appropriate initial step.', 3),
('c9000000-0000-0000-0000-000000000024', 'D', 'Apply bedrails to all four sides of his bed as the primary intervention', false, 'Ruled out because bedrails do not address the underlying medication-related falls risk and can themselves cause injury; medication review is the priority intervention.', 4),
('c9000000-0000-0000-0000-000000000024', 'E', 'Arrange discharge immediately, as ward falls are not clinically significant', false, 'Ruled out because recurrent falls, even without injury, indicate a risk that should be addressed before discharge to reduce risk of future harm.', 5),
('c9000000-0000-0000-0000-000000000025', 'A', 'Vasovagal syncope', false, 'Ruled out because typical vasovagal syncope is usually triggered by prolonged standing, pain, or emotional stress rather than specific head-turning movements, and would not show the specific carotid sinus massage findings described here.', 1),
('c9000000-0000-0000-0000-000000000025', 'B', 'Transient ischaemic attack', false, 'Ruled out because a TIA typically causes focal neurological deficit rather than syncope/collapse, and the diagnostic carotid sinus massage findings point specifically to carotid sinus hypersensitivity.', 2),
('c9000000-0000-0000-0000-000000000025', 'C', 'Epileptic seizure', false, 'Ruled out because there are no described features of a seizure (such as tonic-clonic movements, tongue biting, or prolonged post-ictal confusion), and the diagnostic test findings point to a cardiovascular cause.', 3),
('c9000000-0000-0000-0000-000000000025', 'D', 'Carotid sinus hypersensitivity', true, 'Correct. Syncope or falls provoked by head-turning or neck pressure, with a demonstrable exaggerated bradycardic/hypotensive response on carotid sinus massage under monitoring, is diagnostic of carotid sinus hypersensitivity, an important and treatable cause of unexplained falls and syncope in older adults.', 4),
('c9000000-0000-0000-0000-000000000025', 'E', 'Benign paroxysmal positional vertigo', false, 'Ruled out because BPPV causes vertigo with specific head movements rather than syncope or collapse, and does not explain the carotid sinus massage findings.', 5),
('c9000000-0000-0000-0000-000000000026', 'A', 'Primary hyperparathyroidism', false, $x$Ruled out because primary hyperparathyroidism typically causes raised, not low, serum calcium, which is inconsistent with this patient's biochemistry.$x$, 1),
('c9000000-0000-0000-0000-000000000026', 'B', 'Multiple myeloma', false, 'Ruled out because myeloma classically causes hypercalcaemia, renal impairment, anaemia and bone lesions, which is a different biochemical and clinical pattern from the one described here.', 2),
('c9000000-0000-0000-0000-000000000026', 'C', 'Polymyalgia rheumatica', false, 'Ruled out because polymyalgia rheumatica typically causes proximal muscle pain and stiffness with a markedly raised inflammatory marker (ESR/CRP), not the specific low vitamin D/calcium biochemistry described.', 3),
('c9000000-0000-0000-0000-000000000026', 'D', 'Age-related sarcopenia alone', false, 'Ruled out because the specific biochemical abnormalities (low vitamin D, low calcium, raised alkaline phosphatase) point to a treatable metabolic bone disease (osteomalacia) rather than simple age-related muscle loss.', 4),
('c9000000-0000-0000-0000-000000000026', 'E', 'Vitamin D deficiency with associated osteomalacia and proximal myopathy', true, 'Correct. Limited sun exposure leading to vitamin D deficiency causes proximal muscle weakness (myopathy) and bone pain (osteomalacia), with biochemistry showing low vitamin D and calcium alongside raised alkaline phosphatase; this combination significantly increases falls risk and should be corrected with vitamin D and calcium replacement.', 5),
('c9000000-0000-0000-0000-000000000027', 'A', 'Functional mobility and falls risk, by assessing gait speed, balance and transfer ability', true, 'Correct. The Timed Up and Go test is a simple, validated screening tool for functional mobility; a prolonged completion time is associated with increased falls risk and can help identify patients who need further, more detailed gait and balance assessment.', 1),
('c9000000-0000-0000-0000-000000000027', 'B', 'Cognitive function and executive planning ability', false, 'Ruled out because although some cognitive input is required for any task, the Timed Up and Go primarily assesses physical mobility and balance, not cognition.', 2),
('c9000000-0000-0000-0000-000000000027', 'C', 'Cardiovascular fitness and exercise tolerance', false, 'Ruled out because this is a brief functional mobility test, not a measure of cardiovascular exercise capacity such as a formal exercise tolerance test.', 3),
('c9000000-0000-0000-0000-000000000027', 'D', 'Nutritional status and sarcopenia specifically', false, 'Ruled out because while frailty and sarcopenia can affect performance, the test specifically evaluates functional mobility and balance rather than nutritional status.', 4),
('c9000000-0000-0000-0000-000000000027', 'E', 'Bladder and bowel continence function', false, 'Ruled out because this test has no relationship to continence assessment; it is a mobility and falls-risk screening tool.', 5),
('c9000000-0000-0000-0000-000000000028', 'A', 'Discharge home with head injury advice, as she did not lose consciousness', false, 'Ruled out because anticoagulation is itself an indication for urgent CT head after any head injury, regardless of loss of consciousness or neurological signs, due to the increased bleeding risk.', 1),
('c9000000-0000-0000-0000-000000000028', 'B', 'Withhold warfarin permanently without further assessment', false, 'Ruled out because immediate imaging to exclude intracranial bleeding is the priority; decisions about anticoagulation should follow assessment and be made in the context of her overall stroke and bleeding risk, not as an isolated first step.', 2),
('c9000000-0000-0000-0000-000000000028', 'C', 'Urgent CT head, given her anticoagulation and supratherapeutic INR, even in the absence of focal neurological signs or loss of consciousness', true, 'Correct. Patients on anticoagulation who sustain a head injury are at significantly increased risk of intracranial haemorrhage, and current guidance recommends urgent CT head imaging in this group even without loss of consciousness or focal neurological signs, given the potential for delayed or occult bleeding.', 3),
('c9000000-0000-0000-0000-000000000028', 'D', 'Reverse her anticoagulation with vitamin K before any imaging is performed', false, 'Ruled out because imaging should be obtained urgently to establish whether bleeding has occurred; reversal agents are used once a bleed is confirmed or strongly suspected, not routinely before imaging in an asymptomatic patient.', 4),
('c9000000-0000-0000-0000-000000000028', 'E', 'Arrange a routine outpatient CT head within two weeks', false, 'Ruled out because the combination of anticoagulation and head injury requires urgent, not delayed, imaging due to the risk of evolving intracranial haemorrhage.', 5),
('c9000000-0000-0000-0000-000000000029', 'A', $x$Meniere's disease$x$, false, $x$Ruled out because Meniere's disease typically causes longer episodes of vertigo (minutes to hours) associated with fluctuating hearing loss, tinnitus, and aural fullness, which are absent here.$x$, 1),
('c9000000-0000-0000-0000-000000000029', 'B', 'Benign paroxysmal positional vertigo (BPPV)', true, 'Correct. Brief, recurrent episodes of vertigo lasting seconds to a minute, specifically triggered by changes in head position (such as turning over in bed or looking up), without hearing loss or tinnitus, is the classic presentation of BPPV, caused by displaced otoconia in the semicircular canals.', 2),
('c9000000-0000-0000-0000-000000000029', 'C', 'Vestibular neuritis', false, 'Ruled out because vestibular neuritis causes a single prolonged episode of continuous vertigo lasting days, not brief recurrent positional episodes.', 3),
('c9000000-0000-0000-0000-000000000029', 'D', 'Posterior circulation stroke', false, 'Ruled out because a normal neurological examination and the classic brief, positional, recurrent pattern (rather than persistent vertigo with other neurological signs) make BPPV far more likely than a stroke.', 4),
('c9000000-0000-0000-0000-000000000029', 'E', 'Acoustic neuroma', false, 'Ruled out because acoustic neuroma typically presents with progressive unilateral hearing loss and tinnitus, with vertigo (if present) being less prominent and not classically positional in this brief pattern.', 5),
('c9000000-0000-0000-0000-000000000030', 'A', 'Very fit', false, $x$Ruled out because 'very fit' describes robust, active individuals who exercise regularly and have no functional dependency, which does not match this patient's described needs for assistance.$x$, 1),
('c9000000-0000-0000-0000-000000000030', 'B', 'Managing well', false, $x$Ruled out because 'managing well' describes patients with controlled comorbidities but no significant functional dependency beyond occasional help, whereas this patient needs regular help with multiple instrumental activities.$x$, 2),
('c9000000-0000-0000-0000-000000000030', 'C', 'Severely frail', false, $x$Ruled out because 'severely frail' describes complete dependency for personal care, which does not apply here as she remains independent with personal care.$x$, 3),
('c9000000-0000-0000-0000-000000000030', 'D', 'Mildly frail', true, $x$Correct. This description, needing help with more complex tasks (housework, transportation, outdoor activities) while remaining independent with personal care, and having noticeably slowed with increasing need for assistance over the preceding year, corresponds to 'mildly frail' on the Clinical Frailty Scale.$x$, 4),
('c9000000-0000-0000-0000-000000000030', 'E', 'Terminally ill', false, 'Ruled out because this category applies to patients approaching end of life with a life expectancy of less than six months, which is not described in this scenario.', 5),
('c9000000-0000-0000-0000-000000000031', 'A', 'Dual-energy X-ray absorptiometry (DEXA) scan to assess bone mineral density', true, 'Correct. A vertebral compression fracture occurring after minimal or no trauma (a fragility fracture) is diagnostic of an underlying bone fragility disorder; a DEXA scan should be arranged to quantify bone mineral density and guide treatment, and this patient meets criteria for treatment regardless of the T-score given the fracture itself.', 1),
('c9000000-0000-0000-0000-000000000031', 'B', 'Bone scintigraphy as the first-line investigation', false, 'Ruled out because DEXA, not bone scintigraphy, is the standard first-line investigation for assessing bone density after a fragility fracture; scintigraphy is used for other indications such as detecting metastases or occult fractures.', 2),
('c9000000-0000-0000-0000-000000000031', 'C', 'No further investigation is required, as this is a normal consequence of ageing', false, 'Ruled out because a fragility fracture is not a normal finding and requires investigation and treatment to reduce the risk of further fractures.', 3),
('c9000000-0000-0000-0000-000000000031', 'D', 'Serum protein electrophoresis as the only necessary test', false, 'Ruled out because while myeloma should be considered in the differential of vertebral fracture, particularly with atypical features, DEXA remains the key investigation for assessing osteoporosis as the primary underlying cause here.', 4),
('c9000000-0000-0000-0000-000000000031', 'E', 'PET-CT scan to look for an occult malignancy', false, 'Ruled out because there is nothing in this presentation (age, mechanism, single osteoporotic-pattern fracture) suggesting malignancy; extensive oncological imaging is not indicated as the next step.', 5),
('c9000000-0000-0000-0000-000000000032', 'A', 'Start bisphosphonate therapy immediately based on the T-score alone', false, 'Ruled out because a T-score of -2.0 represents osteopenia, not osteoporosis, and treatment decisions should be guided by overall fracture risk assessment (e.g. FRAX) rather than the DEXA T-score in isolation.', 1),
('c9000000-0000-0000-0000-000000000032', 'B', 'No further assessment is needed since her T-score is above the osteoporosis threshold', false, 'Ruled out because clinical risk factors (family history of hip fracture, excess alcohol use) may still place her at significant fracture risk despite a T-score above -2.5, warranting formal risk calculation.', 2),
('c9000000-0000-0000-0000-000000000032', 'C', 'Repeat the DEXA scan in six months regardless of current risk factors', false, 'Ruled out because DEXA scans are not usually repeated so soon; the priority now is to use the existing result alongside clinical risk factors to calculate fracture risk, not to repeat imaging prematurely.', 3),
('c9000000-0000-0000-0000-000000000032', 'D', 'Calculate her 10-year fracture risk using a validated tool such as FRAX, incorporating clinical risk factors alongside the DEXA result', true, 'Correct. A T-score of -2.0 indicates osteopenia rather than osteoporosis; a validated fracture risk assessment tool (such as FRAX), which combines clinical risk factors (age, family history, alcohol use, etc.) with bone density, is used to estimate absolute fracture risk and determine whether treatment is warranted.', 4),
('c9000000-0000-0000-0000-000000000032', 'E', 'Refer directly for consideration of denosumab without further risk stratification', false, 'Ruled out because treatment decisions, and choice of agent, should follow a formal risk assessment rather than jumping directly to a specific therapy without stratifying risk.', 5),
('c9000000-0000-0000-0000-000000000033', 'A', 'Take it at bedtime lying flat to aid absorption', false, 'Ruled out because lying down after taking an oral bisphosphonate increases the risk of oesophageal reflux and irritation; patients should remain upright after dosing.', 1),
('c9000000-0000-0000-0000-000000000033', 'B', 'Take it first thing in the morning on an empty stomach with a full glass of water, remaining upright for at least 30 minutes and not eating for 30 minutes afterwards', true, 'Correct. Oral bisphosphonates such as alendronic acid have poor bioavailability and can cause oesophageal irritation/ulceration; taking them on an empty stomach with water, remaining upright, and avoiding food for at least 30 minutes reduces the risk of oesophageal side effects and maximises absorption.', 2),
('c9000000-0000-0000-0000-000000000033', 'C', 'Take it with a meal to reduce gastrointestinal side effects', false, 'Ruled out because taking bisphosphonates with food significantly reduces their already limited absorption; they should be taken on an empty stomach.', 3),
('c9000000-0000-0000-0000-000000000033', 'D', 'Take it with a calcium-fortified drink to enhance absorption', false, 'Ruled out because calcium-containing drinks or supplements taken with or close to the dose interfere with absorption of oral bisphosphonates.', 4),
('c9000000-0000-0000-0000-000000000033', 'E', 'No specific precautions are needed as long as the correct dose is taken', false, 'Ruled out because specific administration precautions are essential to reduce oesophageal side effects and ensure adequate absorption of this poorly bioavailable drug.', 5),
('c9000000-0000-0000-0000-000000000034', 'A', 'A typical osteoporotic hip fracture at the femoral neck', false, 'Ruled out because typical osteoporotic fractures occur at the femoral neck after a fall, whereas this describes a femoral shaft fracture with atypical radiographic features and no acute trauma, characteristic of an atypical fracture.', 1),
('c9000000-0000-0000-0000-000000000034', 'B', 'Pathological fracture through a bone metastasis', false, 'Ruled out because the specific radiographic feature of lateral cortical thickening in the context of long-term bisphosphonate use is characteristic of an atypical bisphosphonate-associated fracture, though malignancy should still be excluded if there is diagnostic uncertainty.', 2),
('c9000000-0000-0000-0000-000000000034', 'C', 'Stress fracture unrelated to medication use', false, 'Ruled out because the clinical and radiographic picture, in a patient on long-term bisphosphonates, is specifically characteristic of a bisphosphonate-associated atypical femoral fracture rather than a coincidental stress fracture.', 3),
('c9000000-0000-0000-0000-000000000034', 'D', 'Osteomalacia causing a Looser zone fracture', false, 'Ruled out because Looser zones (pseudofractures) occur in osteomalacia due to inadequate mineralisation, which is a distinct entity from the atypical fracture pattern associated with prolonged bisphosphonate use described here.', 4),
('c9000000-0000-0000-0000-000000000034', 'E', 'Atypical femoral fracture associated with long-term bisphosphonate therapy', true, 'Correct. Prolonged bisphosphonate use is associated with a rare but recognised complication of atypical, low-energy subtrochanteric or femoral shaft fractures, often preceded by prodromal thigh or groin pain and characteristic radiographic features such as lateral cortical thickening ("beaking"); this should prompt review of ongoing bisphosphonate therapy.', 5),
('c9000000-0000-0000-0000-000000000035', 'A', 'Wait until a fragility fracture occurs before considering any bone protection', false, 'Ruled out because steroid-induced osteoporosis should be anticipated and prevented proactively, not managed reactively only after a fracture has already occurred.', 1),
('c9000000-0000-0000-0000-000000000035', 'B', 'No bone protection is required as he is male and below typical osteoporosis screening age', false, 'Ruled out because glucocorticoid-induced bone loss occurs in both sexes and at any adult age when steroid doses and duration are significant; risk assessment should not be deferred based on sex or age alone.', 2),
('c9000000-0000-0000-0000-000000000035', 'C', 'Assess fracture risk and start bone-protective treatment (such as a bisphosphonate) alongside calcium and vitamin D supplementation if indicated, without necessarily waiting for a DEXA scan result', true, 'Correct. Patients starting long-term high-dose glucocorticoids (generally prednisolone 7.5 mg/day or more for 3 months or longer) are at significantly increased fracture risk; bone protection, often with a bisphosphonate plus calcium/vitamin D, should be considered promptly at the time steroids are started rather than delayed pending DEXA results, particularly in higher risk patients.', 3),
('c9000000-0000-0000-0000-000000000035', 'D', 'Arrange a DEXA scan and reassess again in two years before making any decisions on bone protection', false, 'Ruled out because with significant ongoing high-dose steroid use, prompt risk assessment and consideration of bone protection is recommended rather than waiting years to reassess.', 4),
('c9000000-0000-0000-0000-000000000035', 'E', 'Stop the steroids immediately to prevent bone loss', false, 'Ruled out because the steroids are needed to treat his underlying inflammatory condition; the appropriate approach is to add bone protection alongside continued necessary treatment, not to stop essential therapy.', 5),
('c9000000-0000-0000-0000-000000000036', 'A', 'Conservative management with bed rest and analgesia alone', false, 'Ruled out because conservative management of hip fractures in older adults is associated with significantly worse pain control, mobility outcomes and mortality compared with surgical fixation, and is reserved for select cases where surgery is not appropriate.', 1),
('c9000000-0000-0000-0000-000000000036', 'B', 'Immediate discharge home with outpatient physiotherapy', false, 'Ruled out because a displaced hip fracture requires inpatient surgical management; she cannot weight-bear and would not be safe to discharge without treatment.', 2),
('c9000000-0000-0000-0000-000000000036', 'C', 'Prompt surgical fixation (e.g. hemiarthroplasty or total hip replacement depending on patient factors), ideally within 36 hours of admission, alongside orthogeriatric input', true, 'Correct. Displaced intracapsular hip fractures in older adults are generally treated surgically, with arthroplasty (hemiarthroplasty or total hip replacement depending on pre-fracture mobility and cognition) preferred over internal fixation due to the risk of avascular necrosis; timely surgery within around 36 hours, alongside orthogeriatric assessment, improves outcomes.', 3),
('c9000000-0000-0000-0000-000000000036', 'D', 'Skin traction for six weeks followed by reassessment', false, 'Ruled out because prolonged traction is not standard management for hip fractures and delays mobilisation, increasing complication risk compared with prompt surgery.', 4),
('c9000000-0000-0000-0000-000000000036', 'E', 'Delay surgery for several weeks until osteoporosis treatment has been optimised', false, 'Ruled out because surgery should not be delayed for osteoporosis treatment; prompt fixation improves outcomes, and bone protection is addressed afterwards as part of secondary fracture prevention.', 5),
('c9000000-0000-0000-0000-000000000037', 'A', 'A higher dose of the same oral bisphosphonate', false, 'Ruled out because bisphosphonates are renally excreted and require caution or are contraindicated in significant renal impairment; simply increasing the dose would increase toxicity risk rather than address the underlying issue.', 1),
('c9000000-0000-0000-0000-000000000037', 'B', 'Denosumab, as it can be used without dose adjustment even in significant renal impairment, unlike most bisphosphonates', true, 'Correct. Denosumab is a monoclonal antibody that inhibits osteoclast activity and, unlike bisphosphonates, is not renally cleared, making it a suitable option in patients with significant renal impairment where bisphosphonates may be contraindicated or require caution; close monitoring for hypocalcaemia is still required.', 2),
('c9000000-0000-0000-0000-000000000037', 'C', 'Intravenous zoledronic acid at the standard dose without renal adjustment', false, 'Ruled out because intravenous bisphosphonates such as zoledronic acid require dose adjustment or are contraindicated in significant renal impairment due to nephrotoxicity risk.', 3),
('c9000000-0000-0000-0000-000000000037', 'D', 'Stopping all osteoporosis treatment since no options are available in renal impairment', false, 'Ruled out because denosumab provides an effective option that does not require renal dose adjustment, so treatment should not be abandoned.', 4),
('c9000000-0000-0000-0000-000000000037', 'E', 'Hormone replacement therapy as the treatment of choice in this patient', false, 'Ruled out because HRT is not first-line for osteoporosis in an elderly man and is not specifically indicated by his renal impairment; denosumab is the more appropriate consideration here.', 5),
('c9000000-0000-0000-0000-000000000038', 'A', 'There is no clinical significance to missing or delaying a denosumab dose', false, 'Ruled out because missing or stopping denosumab is clinically significant due to the risk of rebound bone loss and vertebral fracture, and requires prompt action.', 1),
('c9000000-0000-0000-0000-000000000038', 'B', 'She should simply switch to calcium and vitamin D supplementation alone going forward', false, 'Ruled out because calcium and vitamin D alone will not prevent the rebound bone loss associated with stopping denosumab; specific bridging anti-resorptive therapy should be considered.', 2),
('c9000000-0000-0000-0000-000000000038', 'C', 'Denosumab has a similar residual protective effect to bisphosphonates after stopping, so delay is not a concern', false, $x$Ruled out because, unlike bisphosphonates which remain in bone for a prolonged period after stopping, denosumab's effect wanes rapidly once doses are missed or discontinued, which is precisely why this is a safety concern.$x$, 3),
('c9000000-0000-0000-0000-000000000038', 'D', 'The dose should be doubled at the next appointment to compensate for the delay', false, 'Ruled out because doubling the dose is not a recommended strategy; the priority is prompt administration of the next dose or bridging therapy, not dose escalation.', 4),
('c9000000-0000-0000-0000-000000000038', 'E', 'Delaying or stopping denosumab carries a risk of rapid rebound bone loss and an increased risk of multiple vertebral fractures; the injection should be given as soon as possible or bridging therapy considered', true, $x$Correct. Unlike bisphosphonates, denosumab's effect is not retained after stopping; discontinuation or significant delay is associated with rapid rebound bone turnover and a recognised risk of multiple vertebral fractures, so missed or discontinued doses should prompt urgent review and consideration of bridging therapy (e.g. a bisphosphonate) if denosumab is to be stopped.$x$, 5),
('c9000000-0000-0000-0000-000000000039', 'A', 'Osteomalacia due to vitamin D deficiency', true, 'Correct. The combination of bone pain, proximal muscle weakness, low calcium and phosphate, low vitamin D, and markedly raised alkaline phosphatase indicates a mineralisation defect (osteomalacia) rather than simple osteoporosis; osteomalacia can also lower bone density on DEXA, but the biochemical picture is the key distinguishing feature.', 1),
('c9000000-0000-0000-0000-000000000039', 'B', 'Simple age-related osteoporosis', false, 'Ruled out because osteoporosis alone typically has normal calcium, phosphate and alkaline phosphatase; the abnormal biochemistry here points to osteomalacia as the underlying process.', 2),
('c9000000-0000-0000-0000-000000000039', 'C', $x$Paget's disease of bone$x$, false, $x$Ruled out because although Paget's disease raises alkaline phosphatase, calcium and phosphate are usually normal, and the clinical picture (bone pain, deformity) differs from the diffuse pain, weakness and low calcium/vitamin D seen here.$x$, 3),
('c9000000-0000-0000-0000-000000000039', 'D', 'Primary hyperparathyroidism', false, $x$Ruled out because primary hyperparathyroidism causes raised, not low, serum calcium, which is inconsistent with this patient's biochemistry.$x$, 4),
('c9000000-0000-0000-0000-000000000039', 'E', 'Multiple myeloma', false, 'Ruled out because myeloma typically causes hypercalcaemia and renal impairment with a different biochemical pattern, rather than the low calcium/phosphate/vitamin D picture seen in osteomalacia.', 5),
('c9000000-0000-0000-0000-000000000040', 'A', 'No further action is required, as wrist fractures are not associated with underlying bone fragility', false, 'Ruled out because a wrist fracture from a fall from standing height is a fragility fracture and is a recognised marker of increased future fracture risk, including hip fracture, warranting assessment.', 1),
('c9000000-0000-0000-0000-000000000040', 'B', 'Immobilise the wrist and discharge with no further follow-up regarding bone health', false, 'Ruled out because while the acute fracture requires appropriate orthopaedic management, this does not address the underlying bone fragility and falls risk that led to the fracture.', 2),
('c9000000-0000-0000-0000-000000000040', 'C', 'Start empirical bisphosphonate therapy without any assessment of bone density or falls risk', false, 'Ruled out because treatment decisions should be guided by a proper assessment (DEXA, fracture risk calculation, falls assessment) coordinated through a fracture liaison pathway, rather than starting therapy blindly.', 3),
('c9000000-0000-0000-0000-000000000040', 'D', 'Refer to a fracture liaison service for assessment of bone health and falls risk', true, 'Correct. Fracture liaison services provide a systematic pathway to identify patients with fragility fractures, arrange bone density assessment (e.g. DEXA), evaluate falls risk, and initiate appropriate treatment to reduce the risk of further fractures; referral is recommended for any patient over 50 with a fragility fracture.', 4),
('c9000000-0000-0000-0000-000000000040', 'E', 'Refer for genetic testing for osteogenesis imperfecta', false, 'Ruled out because this presentation in a 76-year-old with a fall-related wrist fracture is consistent with common age-related osteoporosis, not a rare genetic bone disorder, and genetic testing is not indicated.', 5),
('c9000000-0000-0000-0000-000000000041', 'A', 'Continue the omeprazole indefinitely without review, as it is generally safe long-term', false, 'Ruled out because long-term PPI use without an ongoing indication carries recognised risks and should be periodically reviewed, not continued indefinitely by default.', 1),
('c9000000-0000-0000-0000-000000000041', 'B', 'Increase the dose to ensure adequate acid suppression', false, 'Ruled out because there is no indication described that would require increasing the dose; the priority is reviewing whether the drug is still needed at all.', 2),
('c9000000-0000-0000-0000-000000000041', 'C', 'Review the ongoing indication and consider stepping down or stopping the proton pump inhibitor if there is no continuing indication', true, 'Correct. Long-term proton pump inhibitor use without a clear ongoing indication is a recognised example of inappropriate prescribing in older adults (highlighted in STOPP criteria) and carries risks including fracture, Clostridioides difficile infection, and micronutrient deficiency; the indication should be reviewed and the drug stepped down or stopped if no longer needed.', 3),
('c9000000-0000-0000-0000-000000000041', 'D', 'Switch to a different proton pump inhibitor at an equivalent dose', false, 'Ruled out because switching within the same drug class does not address the underlying issue of a medication continuing without a clear ongoing indication.', 4),
('c9000000-0000-0000-0000-000000000041', 'E', 'Add a histamine H2-receptor antagonist in addition to the PPI', false, 'Ruled out because adding a second acid-suppressing agent is unnecessary and does not address the core issue of reviewing whether the PPI itself is still indicated.', 5),
('c9000000-0000-0000-0000-000000000042', 'A', 'A new primary psychiatric illness unrelated to her medications', false, 'Ruled out because the combination of specific anticholinergic symptoms (dry mouth, blurred vision, constipation) alongside confusion strongly points to a medication-related cause rather than a new primary psychiatric diagnosis.', 1),
('c9000000-0000-0000-0000-000000000042', 'B', 'Normal age-related cognitive decline', false, 'Ruled out because these specific physical anticholinergic symptoms alongside new confusion indicate an identifiable, reversible drug-related cause rather than expected ageing.', 2),
('c9000000-0000-0000-0000-000000000042', 'C', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency does not typically cause this constellation of anticholinergic symptoms (dry mouth, blurred vision) and there is a more likely explanation given her medication list.', 3),
('c9000000-0000-0000-0000-000000000042', 'D', 'Underlying undiagnosed dementia presenting acutely', false, 'Ruled out because an acute presentation with a clear pharmacological explanation (cumulative anticholinergic burden) should be addressed and reversed before attributing symptoms to an underlying dementia.', 4),
('c9000000-0000-0000-0000-000000000042', 'E', 'Cumulative anticholinergic burden from multiple anticholinergic medications', true, 'Correct. Amitriptyline, oxybutynin and chlorphenamine all have significant anticholinergic activity; taken together, their cumulative anticholinergic burden can cause confusion, dry mouth, blurred vision and constipation, particularly in older adults who are more susceptible to these effects.', 5),
('c9000000-0000-0000-0000-000000000043', 'A', 'Progression of his underlying chronic kidney disease unrelated to any medication', false, 'Ruled out because the temporal relationship with starting an NSAID alongside his existing ACE inhibitor and diuretic strongly suggests a drug-induced acute insult rather than simple chronic disease progression.', 1),
('c9000000-0000-0000-0000-000000000043', 'B', 'Dehydration alone, unrelated to his medications', false, 'Ruled out because although dehydration can contribute, the specific combination of nephrotoxic and renally-acting drugs (ACE inhibitor, diuretic, NSAID) is the recognised precipitant here, not dehydration in isolation.', 2),
('c9000000-0000-0000-0000-000000000043', 'C', 'An allergic interstitial nephritis reaction to furosemide', false, $x$Ruled out because while NSAIDs and some diuretics can rarely cause interstitial nephritis, the classic and most likely explanation given this drug combination and timeline is haemodynamically-mediated AKI from the 'triple whammy' effect.$x$, 3),
('c9000000-0000-0000-0000-000000000043', 'D', 'The combination of an ACE inhibitor, a diuretic, and an NSAID ("triple whammy") causing acute kidney injury', true, 'Correct. The combination of an ACE inhibitor, a diuretic, and an NSAID together significantly impairs renal autoregulation and commonly precipitates acute kidney injury, particularly in older patients with pre-existing chronic kidney disease; NSAIDs should generally be avoided in this context.', 4),
('c9000000-0000-0000-0000-000000000043', 'E', 'Urinary tract obstruction from an enlarged prostate', false, 'Ruled out because there is no history or examination finding suggesting obstruction, and the clear temporal link to starting an NSAID with his existing ACE inhibitor/diuretic combination is the more likely cause.', 5),
('c9000000-0000-0000-0000-000000000044', 'A', 'Simply provide the discharge letter and assume the patient will manage independently without further explanation', false, 'Ruled out because complex medication changes without clear explanation increase the risk of confusion, non-adherence, and medication errors, particularly in older patients.', 1),
('c9000000-0000-0000-0000-000000000044', 'B', 'Perform thorough medication reconciliation, clearly communicating changes (started, stopped, dose-altered) to the patient, carers, and his GP', true, 'Correct. Medication reconciliation at discharge, which involves comparing pre-admission and discharge medication lists and clearly documenting and communicating any changes to the patient, carers and primary care, is essential to prevent medication errors, omissions, or unintentional duplication after a hospital stay with multiple changes.', 2),
('c9000000-0000-0000-0000-000000000044', 'C', 'Restart all of his pre-admission medications alongside the new ones started in hospital', false, 'Ruled out because restarting old medications without reconciling against the changes made in hospital risks unintentional duplication or reintroducing medications that were deliberately stopped for good reason.', 3),
('c9000000-0000-0000-0000-000000000044', 'D', 'Leave medication reconciliation to be completed at his next routine GP appointment in several months', false, 'Ruled out because delaying reconciliation for months increases the risk of harm from confusion or errors in the interim; reconciliation should happen at the point of discharge.', 4),
('c9000000-0000-0000-0000-000000000044', 'E', 'Discontinue all new medications started in hospital and revert to his original list', false, 'Ruled out because new medications may have been started for good clinical reasons; the correct approach is careful reconciliation and clear communication, not blanket reversal.', 5),
('c9000000-0000-0000-0000-000000000045', 'A', 'Digoxin toxicity secondary to reduced renal clearance in the context of acute kidney injury', true, 'Correct. Digoxin is renally excreted, and acute kidney injury reduces its clearance, increasing serum digoxin levels; nausea, anorexia and visual disturbances (including xanthopsia, yellow-tinged vision) are classic features of digoxin toxicity and warrant urgent digoxin level measurement and dose review.', 1),
('c9000000-0000-0000-0000-000000000045', 'B', 'A new primary ophthalmological disease causing her visual symptoms', false, 'Ruled out because the combination of gastrointestinal symptoms and characteristic yellow-tinged vision in the context of worsening renal function and digoxin use points specifically to digoxin toxicity rather than a primary eye disease.', 2),
('c9000000-0000-0000-0000-000000000045', 'C', 'Worsening heart failure causing her symptoms', false, 'Ruled out because while heart failure can cause some overlapping symptoms, the specific combination of nausea, anorexia and yellow-tinged visual disturbance is characteristic of digoxin toxicity, which should be actively excluded given her renal deterioration.', 3),
('c9000000-0000-0000-0000-000000000045', 'D', 'Side effects of her chest infection alone, unrelated to medication', false, 'Ruled out because the classic combination of gastrointestinal and visual symptoms, occurring alongside significant renal impairment in a patient on digoxin, is specifically suggestive of digoxin toxicity rather than being explained by the infection alone.', 4),
('c9000000-0000-0000-0000-000000000045', 'E', 'Hypoglycaemia related to acute illness', false, 'Ruled out because there is no mention of diabetes or hypoglycaemic medication, and the described symptom pattern is classic for digoxin toxicity rather than hypoglycaemia.', 5),
('c9000000-0000-0000-0000-000000000046', 'A', 'Spontaneous progression of his underlying valve disease causing bleeding', false, 'Ruled out because valve disease itself does not cause a rise in INR or bleeding tendency; the clear temporal association with starting clarithromycin points to a drug interaction.', 1),
('c9000000-0000-0000-0000-000000000046', 'B', 'Dietary vitamin K deficiency unrelated to his new antibiotic', false, 'Ruled out because there is no history suggesting a sudden dietary change, and the temporal link with starting clarithromycin is a much more likely explanation for the raised INR.', 2),
('c9000000-0000-0000-0000-000000000046', 'C', 'Clarithromycin inhibiting warfarin metabolism, leading to a supratherapeutic INR and bleeding risk', true, 'Correct. Macrolide antibiotics such as clarithromycin inhibit cytochrome P450 enzymes involved in warfarin metabolism, significantly increasing INR and bleeding risk; this is a well-recognised, clinically important drug interaction that should be anticipated whenever new medications are prescribed to a patient on warfarin.', 3),
('c9000000-0000-0000-0000-000000000046', 'D', 'Warfarin resistance developing over time', false, $x$Ruled out because warfarin resistance would cause a low, not high, INR; this presentation clearly shows an elevated INR consistent with potentiation of warfarin's effect.$x$, 4),
('c9000000-0000-0000-0000-000000000046', 'E', 'A new bleeding disorder unrelated to any medication', false, 'Ruled out because the clear temporal relationship with a known interacting drug (clarithromycin) provides a much more likely and common explanation than a new haematological diagnosis.', 5),
('c9000000-0000-0000-0000-000000000047', 'A', 'Continue the statin unchanged, as all preventive medications should be continued regardless of prognosis', false, 'Ruled out because continuing medications with no realistic prospect of benefit in someone with a limited life expectancy adds burden without corresponding benefit; a goals-of-care based review is more appropriate.', 1),
('c9000000-0000-0000-0000-000000000047', 'B', 'Increase the statin dose to further reduce cardiovascular risk', false, 'Ruled out because increasing a preventive medication dose is not appropriate when the overall goal should be to reduce unnecessary treatment burden given her limited life expectancy and lack of symptomatic benefit.', 2),
('c9000000-0000-0000-0000-000000000047', 'C', 'Switch to a different statin at an equivalent dose', false, 'Ruled out because switching within the same drug class does not address the fundamental question of whether ongoing statin therapy is appropriate given her prognosis and goals of care.', 3),
('c9000000-0000-0000-0000-000000000047', 'D', 'Refer to a specialist lipid clinic for further statin optimisation', false, 'Ruled out because specialist optimisation of long-term cardiovascular risk reduction is not appropriate or beneficial in this context of advanced dementia and limited life expectancy.', 4),
('c9000000-0000-0000-0000-000000000047', 'E', $x$Review the goals of care with the patient's family and consider stopping the statin, as long-term preventive medications with no short-term symptomatic benefit are often inappropriate in advanced frailty with limited life expectancy$x$, true, 'Correct. In patients with advanced dementia and limited life expectancy, the benefits of long-term preventive medications such as statins (which take years to show benefit) are unlikely to be realised, while pill burden, side effects, and cost remain; deprescribing after discussion with family/carers about goals of care is generally appropriate.', 5),
('c9000000-0000-0000-0000-000000000048', 'A', 'Advise increasing dietary fibre alone, as this will fully resolve opioid-induced constipation', false, 'Ruled out because bulk-forming laxatives/fibre alone are generally not effective, and can worsen symptoms, in opioid-induced constipation; a stimulant laxative is more appropriate.', 1),
('c9000000-0000-0000-0000-000000000048', 'B', 'Stop all oral fluids until the constipation resolves', false, 'Ruled out because reducing fluid intake would worsen constipation and risks dehydration; adequate hydration should be maintained.', 2),
('c9000000-0000-0000-0000-000000000048', 'C', 'Increase the dose of codeine to reduce his need to strain by controlling his pain more effectively', false, 'Ruled out because increasing the opioid dose would worsen constipation, not resolve it, since opioids are the direct cause of the bowel symptoms.', 3),
('c9000000-0000-0000-0000-000000000048', 'D', 'Start a regular stimulant laxative (with a softener if needed) and review ongoing need for the opioid analgesic', true, 'Correct. Opioids commonly cause constipation through reduced gut motility, and this should be anticipated and managed proactively with a stimulant laxative (often combined with a stool softener); the ongoing necessity, dose and alternatives for his opioid analgesic should also be reviewed as part of a broader pain management plan.', 4),
('c9000000-0000-0000-0000-000000000048', 'E', 'Reassure him that this is a normal consequence of ageing requiring no specific treatment', false, 'Ruled out because opioid-induced constipation is a common, predictable, and treatable side effect that should be proactively managed, not dismissed as normal ageing.', 5),
('c9000000-0000-0000-0000-000000000049', 'A', 'An unrelated new neurological event requiring urgent CT head as the priority action', false, 'Ruled out because the clear temporal relationship with starting a sedative medication, alongside reported drowsiness and unsteadiness, points strongly to a medication-related cause rather than a new neurological event, although head injury from the fall itself should still be assessed as appropriate.', 1),
('c9000000-0000-0000-0000-000000000049', 'B', 'Sedative effect of the newly started benzodiazepine (temazepam)', true, 'Correct. Benzodiazepines cause sedation, impaired balance and slowed reaction times, and are well-recognised to increase falls risk in older adults, particularly soon after starting or increasing the dose; this should prompt review and, where possible, discontinuation in favour of non-pharmacological approaches to insomnia.', 2),
('c9000000-0000-0000-0000-000000000049', 'C', 'Normal grief reaction to bereavement causing her fall', false, 'Ruled out because while grief may affect sleep and mood, it does not directly cause the drowsiness and unsteadiness leading to a fall; the sedative medication is the more likely direct contributor.', 3),
('c9000000-0000-0000-0000-000000000049', 'D', 'Dehydration secondary to reduced appetite after bereavement', false, 'Ruled out because although reduced intake can contribute to falls risk in some cases, the specific onset of drowsiness and unsteadiness since starting temazepam points more directly to a medication effect.', 4),
('c9000000-0000-0000-0000-000000000049', 'E', 'Vitamin D deficiency as the primary cause', false, 'Ruled out because there is no information suggesting vitamin D deficiency, and the clear temporal link to starting a sedative drug is the most likely explanation for her new symptoms and fall.', 5),
('c9000000-0000-0000-0000-000000000050', 'A', 'Conduct a structured medication review (e.g. using STOPP/START criteria), specifically addressing the inappropriate combination of an anticoagulant with regular NSAID use and overall antihypertensive burden', true, 'Correct. A structured medication review is needed given the number of medications and specific safety concerns: regular NSAID use alongside an anticoagulant (apixaban) significantly increases bleeding risk and is a recognised inappropriate combination, and the combination of three antihypertensive/rate-limiting agents (ramipril, bisoprolol, amlodipine) could be contributing to his dizziness.', 1),
('c9000000-0000-0000-0000-000000000050', 'B', 'Continue all current medications unchanged, as each was started for a valid indication', false, 'Ruled out because even when each drug was appropriately started, the cumulative combination (particularly anticoagulant plus NSAID, and multiple blood-pressure-lowering drugs) creates significant safety risks that require active review, not passive continuation.', 2),
('c9000000-0000-0000-0000-000000000050', 'C', 'Stop the apixaban since he is at risk of bleeding, but leave the ibuprofen unchanged', false, 'Ruled out because stopping anticoagulation would remove essential stroke prevention for his atrial fibrillation; the correct action is to address the NSAID (the avoidable, non-essential drug) rather than stopping the anticoagulant.', 3),
('c9000000-0000-0000-0000-000000000050', 'D', 'Add a proton pump inhibitor and continue the ibuprofen and apixaban together long-term', false, 'Ruled out because while gastroprotection can reduce some risk, the combination of NSAID and anticoagulant carries substantial bleeding risk that is best managed by stopping the avoidable NSAID rather than simply adding another drug.', 4),
('c9000000-0000-0000-0000-000000000050', 'E', 'Refer him for bariatric surgery assessment to reduce his overall medication burden', false, 'Ruled out because this is not relevant to his current presentation or an appropriate response to a polypharmacy safety concern requiring medication review.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c9000000-0000-0000-0000-000000000001', 'In older adults, a urinary tract infection commonly presents atypically with new confusion, functional decline, or falls rather than classic dysuria.', 1),
('c9000000-0000-0000-0000-000000000001', 'Asymptomatic bacteriuria is common in older people and should not be treated; treatment decisions should be based on new symptoms, not urinalysis alone.', 2),
('c9000000-0000-0000-0000-000000000001', 'New incontinence should always prompt a search for a reversible acute cause (e.g. infection, faecal impaction, delirium) before assuming a chronic bladder problem.', 3),
('c9000000-0000-0000-0000-000000000002', 'Acute urinary retention is a urological emergency requiring prompt catheterisation to relieve pain and prevent renal injury.', 1),
('c9000000-0000-0000-0000-000000000002', 'Anticholinergic and sympathomimetic drugs (e.g. antihistamines, decongestants) can precipitate acute retention in men with underlying prostatic enlargement.', 2),
('c9000000-0000-0000-0000-000000000002', 'After decompression, urine output should be monitored for post-obstructive diuresis, which can cause significant fluid and electrolyte shifts.', 3),
('c9000000-0000-0000-0000-000000000003', 'Overflow diarrhoea from faecal impaction is a common and under-recognised cause of new faecal incontinence in frail older adults.', 1),
('c9000000-0000-0000-0000-000000000003', 'Opioids are a major contributor to constipation and impaction in older patients and should prompt co-prescription of a laxative when started.', 2),
('c9000000-0000-0000-0000-000000000003', 'Digital rectal examination is essential in the assessment of new incontinence to identify impaction before assuming an infective or functional cause.', 3),
('c9000000-0000-0000-0000-000000000004', 'Hospital-associated deconditioning is common in older adults and can significantly reduce independence even after the acute illness resolves.', 1),
('c9000000-0000-0000-0000-000000000004', 'A comprehensive, multidisciplinary functional assessment (physiotherapy, occupational therapy) should precede discharge planning when function has changed during admission.', 2),
('c9000000-0000-0000-0000-000000000004', 'Discharge planning should be based on current functional ability and home circumstances, not assumed from premorbid independence.', 3),
('c9000000-0000-0000-0000-000000000005', 'Anticholinergic drugs, including oxybutynin, contribute significantly to anticholinergic burden and are a recognised cause of confusion and falls in older adults.', 1),
('c9000000-0000-0000-0000-000000000005', 'In patients with cognitive impairment, bladder-selective antimuscarinics or beta-3 agonists (e.g. mirabegron) are generally preferred over drugs with high central anticholinergic activity.', 2),
('c9000000-0000-0000-0000-000000000005', 'Non-pharmacological measures (bladder training, scheduled voiding) should be optimised first, and any drug choice should weigh anticholinergic burden against benefit.', 3),
('c9000000-0000-0000-0000-000000000006', 'Bacteriuria is expected in almost all patients with long-term catheters and should not be treated in the absence of systemic symptoms.', 1),
('c9000000-0000-0000-0000-000000000006', 'Urinalysis (leucocytes/nitrites) is unreliable for diagnosing catheter-associated urinary tract infection; diagnosis requires new systemic or localising symptoms.', 2),
('c9000000-0000-0000-0000-000000000006', 'Treating asymptomatic bacteriuria contributes to antimicrobial resistance and provides no clinical benefit.', 3),
('c9000000-0000-0000-0000-000000000007', 'Pressure ulcer prevention relies on regular repositioning, pressure-redistributing equipment, skin inspection, and optimising nutrition and hydration.', 1),
('c9000000-0000-0000-0000-000000000007', 'Validated risk assessment tools (e.g. Waterlow) should be used on admission and repeated regularly in immobile patients to guide preventive strategies.', 2),
('c9000000-0000-0000-0000-000000000007', 'Prevention must begin as soon as a patient is identified as high risk, not after skin breakdown occurs.', 3),
('c9000000-0000-0000-0000-000000000008', 'A high post-void residual on bladder scan indicates retention with overflow, which should prompt catheterisation and search for a reversible cause.', 1),
('c9000000-0000-0000-0000-000000000008', 'Severe constipation/faecal loading is a common precipitant of both urinary retention and delirium/agitation in older patients and must be actively assessed and treated.', 2),
('c9000000-0000-0000-0000-000000000008', 'New incontinence in a patient with dementia should never be assumed to be simply disease progression without excluding reversible causes.', 3),
('c9000000-0000-0000-0000-000000000009', 'Stress incontinence results from weakened pelvic floor or urethral sphincter support, classically triggered by coughing, sneezing, laughing or lifting.', 1),
('c9000000-0000-0000-0000-000000000009', 'First-line management of stress incontinence is supervised pelvic floor muscle training for at least three months before considering surgical options.', 2),
('c9000000-0000-0000-0000-000000000009', 'Distinguishing stress from urge incontinence by trigger and symptom pattern guides appropriate first-line treatment.', 3),
('c9000000-0000-0000-0000-000000000010', 'Discharge planning for older patients should account for current functional status, home environment (e.g. stairs), and available support, not just clinical resolution of the acute illness.', 1),
('c9000000-0000-0000-0000-000000000010', 'Occupational therapy input, including practical assessments like stair negotiation, is key to determining whether a discharge destination is safe.', 2),
('c9000000-0000-0000-0000-000000000010', 'Social circumstances (living alone, lack of family support) are an essential part of safe discharge planning in frail older patients.', 3),
('c9000000-0000-0000-0000-000000000011', 'Delirium can present as hypoactive (withdrawn, drowsy, quiet) as well as hyperactive (agitated); hypoactive delirium is easily missed and carries similar risk.', 1),
('c9000000-0000-0000-0000-000000000011', $x$The 4AT is a validated, rapid screening tool for delirium that does not require the patient's full cooperation and can be completed quickly at the bedside.$x$, 2),
('c9000000-0000-0000-0000-000000000011', 'Post-operative older patients are at particularly high risk of delirium, and any acute change in cognition or behaviour should trigger delirium screening.', 3),
('c9000000-0000-0000-0000-000000000012', 'Delirium: acute onset, fluctuating course, impaired attention and often altered consciousness; dementia: insidious onset, chronic progressive course, typically preserved consciousness until late stages.', 1),
('c9000000-0000-0000-0000-000000000012', 'A clear history of acute change from a previously stable cognitive baseline is the single most useful feature in distinguishing delirium from dementia.', 2),
('c9000000-0000-0000-0000-000000000012', 'Delirium and dementia frequently coexist; a patient with dementia can also develop superimposed delirium, and an acute change should always prompt investigation for a reversible cause.', 3),
('c9000000-0000-0000-0000-000000000013', $x$Alzheimer's disease is the most common cause of dementia, typically presenting with early, progressive episodic memory loss and gradual functional decline.$x$, 1),
('c9000000-0000-0000-0000-000000000013', $x$Neuroimaging in Alzheimer's disease often shows generalised atrophy with disproportionate hippocampal/medial temporal lobe involvement.$x$, 2),
('c9000000-0000-0000-0000-000000000013', $x$Distinguishing dementia subtypes by their characteristic early features (memory in Alzheimer's, behaviour/language in frontotemporal, fluctuating cognition/hallucinations in Lewy body, stepwise decline in vascular) guides diagnosis and management.$x$, 3),
('c9000000-0000-0000-0000-000000000014', 'Delirium tremens typically occurs 48-96 hours after the last alcoholic drink and presents with agitation, tremor, autonomic instability and hallucinations; it carries significant mortality if untreated.', 1),
('c9000000-0000-0000-0000-000000000014', 'Benzodiazepines are first-line treatment for alcohol withdrawal and delirium tremens; symptom-triggered or fixed-dose reducing regimens are both used depending on setting.', 2),
('c9000000-0000-0000-0000-000000000014', $x$Thiamine should be given before or with glucose in at-risk patients to prevent precipitating Wernicke's encephalopathy.$x$, 3),
('c9000000-0000-0000-0000-000000000015', 'Non-pharmacological strategies are first-line for behavioural and psychological symptoms of dementia; antipsychotics are reserved for severe risk when these measures fail.', 1),
('c9000000-0000-0000-0000-000000000015', 'Antipsychotics carry an increased risk of stroke and mortality in patients with dementia and should be used at the lowest effective dose for the shortest possible time.', 2),
('c9000000-0000-0000-0000-000000000015', 'Dementia with Lewy bodies is associated with severe, potentially life-threatening antipsychotic sensitivity and must be considered before prescribing.', 3),
('c9000000-0000-0000-0000-000000000016', 'Dementia with Lewy bodies features fluctuating cognition, recurrent visual hallucinations, and spontaneous parkinsonism, often with rapid eye movement sleep behaviour disorder.', 1),
('c9000000-0000-0000-0000-000000000016', 'Patients with Lewy body dementia can have severe, sometimes life-threatening sensitivity reactions to antipsychotic medications, so these should be avoided or used with extreme caution.', 2),
('c9000000-0000-0000-0000-000000000016', 'Cholinesterase inhibitors can be particularly effective for cognitive and neuropsychiatric symptoms in dementia with Lewy bodies.', 3),
('c9000000-0000-0000-0000-000000000017', 'Delirium should always be considered to have a treatable underlying cause until proven otherwise, especially in patients with pre-existing dementia.', 1),
('c9000000-0000-0000-0000-000000000017', 'A systematic screen for precipitants (infection, medications, metabolic disturbance, constipation, pain, hypoxia) is essential in the assessment of new confusion.', 2),
('c9000000-0000-0000-0000-000000000017', 'Confusion in dementia is not inevitable disease progression; an acute change over days warrants active investigation.', 3),
('c9000000-0000-0000-0000-000000000018', 'Capacity is decision-specific and time-specific; a diagnosis such as dementia does not automatically mean a patient lacks capacity for every decision.', 1),
('c9000000-0000-0000-0000-000000000018', 'The two-stage test for capacity requires an impairment of mind or brain function, and an inability to understand, retain, use/weigh information, or communicate the decision.', 2),
('c9000000-0000-0000-0000-000000000018', 'Where a patient lacks capacity, decisions should be made in their best interests, taking into account their previously expressed wishes and, where practical, input from family.', 3),
('c9000000-0000-0000-0000-000000000019', 'Multicomponent, non-pharmacological interventions are the most evidence-based approach to delirium prevention in hospitalised older adults.', 1),
('c9000000-0000-0000-0000-000000000019', 'Key modifiable risk factors for delirium include dehydration, immobility, sensory impairment, sleep disruption, pain, constipation and polypharmacy.', 2),
('c9000000-0000-0000-0000-000000000019', 'Pharmacological prophylaxis (e.g. antipsychotics or sedatives) has not been shown to reliably prevent delirium and carries additional risks in this population.', 3),
('c9000000-0000-0000-0000-000000000020', $x$Depression can mimic dementia ('pseudodementia'), often with a more rapid onset, prominent mood symptoms, and inconsistent effort on cognitive testing that improves with encouragement.$x$, 1),
('c9000000-0000-0000-0000-000000000020', 'True dementia typically shows a slow, insidious decline with consistent effort but genuine inability to perform tasks, regardless of encouragement.', 2),
('c9000000-0000-0000-0000-000000000020', 'Screening for depression is an important part of the assessment of any older patient presenting with new cognitive complaints, as it is a treatable cause of apparent cognitive impairment.', 3),
('c9000000-0000-0000-0000-000000000021', 'Lying-and-standing blood pressure measurement is an essential, simple bedside test in the assessment of falls in older adults.', 1),
('c9000000-0000-0000-0000-000000000021', 'A fall in systolic BP of 20 mmHg or more (or diastolic 10 mmHg or more) within 3 minutes of standing defines orthostatic hypotension.', 2),
('c9000000-0000-0000-0000-000000000021', 'Antihypertensive and diuretic medications are common, modifiable contributors to postural hypotension and should be reviewed after a fall.', 3),
('c9000000-0000-0000-0000-000000000022', 'Recurrent falls, or a single fall with injury or high risk features, should trigger a multifactorial falls risk assessment.', 1),
('c9000000-0000-0000-0000-000000000022', 'Key components of falls assessment include gait and balance, vision, cognition, cardiovascular causes (including postural BP), medication review, and home environment.', 2),
('c9000000-0000-0000-0000-000000000022', 'The goal of falls assessment is to identify modifiable risk factors to reduce the risk of future falls, not simply to manage the immediate injury.', 3),
('c9000000-0000-0000-0000-000000000023', 'The frailty phenotype (Fried criteria) comprises unintentional weight loss, self-reported exhaustion, weakness (grip strength), slow gait speed, and low physical activity; three or more features define frailty.', 1),
('c9000000-0000-0000-0000-000000000023', 'Frailty is associated with increased risk of falls, hospitalisation, disability and mortality, and should prompt comprehensive geriatric assessment.', 2),
('c9000000-0000-0000-0000-000000000023', 'Identifying frailty allows for proactive, individualised management planning rather than reactive management of its complications.', 3),
('c9000000-0000-0000-0000-000000000024', 'Sedatives, hypnotics, antihypertensives and drugs with anticholinergic effects are well-recognised contributors to falls risk in older adults.', 1),
('c9000000-0000-0000-0000-000000000024', 'A structured medication review (e.g. using STOPP/START criteria) should be part of the assessment and management of any older patient who falls.', 2),
('c9000000-0000-0000-0000-000000000024', 'Non-pharmacological safety measures (e.g. supervision, bedrails) do not replace the need to address modifiable medication-related risk factors.', 3),
('c9000000-0000-0000-0000-000000000025', 'Carotid sinus hypersensitivity should be considered in older adults with unexplained falls or syncope, particularly when triggered by head-turning, shaving, or tight collars.', 1),
('c9000000-0000-0000-0000-000000000025', 'Carotid sinus massage with continuous ECG and blood pressure monitoring is used to diagnose carotid sinus hypersensitivity, defined by significant asystole and/or blood pressure drop.', 2),
('c9000000-0000-0000-0000-000000000025', 'Permanent pacing may be indicated for the cardioinhibitory form of carotid sinus hypersensitivity causing recurrent syncope or falls.', 3),
('c9000000-0000-0000-0000-000000000026', 'Vitamin D deficiency causes proximal myopathy and bone pain (osteomalacia) and is a common, reversible contributor to falls risk in housebound older adults.', 1),
('c9000000-0000-0000-0000-000000000026', 'Typical biochemistry in osteomalacia shows low vitamin D, low or low-normal calcium and phosphate, and raised alkaline phosphatase.', 2),
('c9000000-0000-0000-0000-000000000026', 'Correcting vitamin D deficiency (and any associated hypocalcaemia) can improve muscle strength and reduce falls risk in deficient older patients.', 3),
('c9000000-0000-0000-0000-000000000027', 'The Timed Up and Go test is a quick, widely used screening tool for functional mobility and falls risk in older adults.', 1),
('c9000000-0000-0000-0000-000000000027', 'A completion time of greater than 12 seconds (thresholds vary by source) is generally associated with increased falls risk and should prompt further assessment.', 2),
('c9000000-0000-0000-0000-000000000027', 'Simple functional tests like this complement, but do not replace, a full multifactorial falls risk assessment.', 3),
('c9000000-0000-0000-0000-000000000028', 'Any head injury in a patient on anticoagulation warrants urgent CT head imaging, regardless of loss of consciousness or the presence of focal neurological signs.', 1),
('c9000000-0000-0000-0000-000000000028', 'A supratherapeutic INR further increases bleeding risk and should heighten, not lower, the threshold for urgent imaging after a fall with head injury.', 2),
('c9000000-0000-0000-0000-000000000028', 'Falls with head injury in anticoagulated patients can result in delayed presentation of intracranial haemorrhage, so safety netting advice is also important even after a normal initial scan.', 3),
('c9000000-0000-0000-0000-000000000029', 'BPPV is characterised by brief (seconds to under a minute), recurrent vertigo triggered specifically by head position changes, without hearing loss or tinnitus.', 1),
('c9000000-0000-0000-0000-000000000029', 'The Dix-Hallpike test is used to confirm the diagnosis of BPPV by reproducing the characteristic nystagmus and symptoms.', 2),
('c9000000-0000-0000-0000-000000000029', 'The Epley manoeuvre is an effective first-line treatment for posterior canal BPPV and can rapidly resolve symptoms and reduce associated falls risk.', 3),
('c9000000-0000-0000-0000-000000000030', $x$The Clinical Frailty Scale is a simple, widely used tool ranging from 'very fit' to 'terminally ill', used to summarise a patient's overall level of frailty and guide shared decision-making.$x$, 1),
('c9000000-0000-0000-0000-000000000030', 'Mild frailty is characterised by increasing need for help with instrumental activities of daily living (e.g. finances, transport, heavy housework) while personal care remains independent.', 2),
('c9000000-0000-0000-0000-000000000030', 'Frailty scoring supports, but should never replace, individualised clinical judgement and discussion with the patient and family about goals of care.', 3),
('c9000000-0000-0000-0000-000000000031', 'A fracture occurring after a fall from standing height or less (a fragility fracture) should always prompt assessment for osteoporosis.', 1),
('c9000000-0000-0000-0000-000000000031', 'DEXA scanning quantifies bone mineral density (T-score) and is central to diagnosing osteoporosis and guiding treatment decisions.', 2),
('c9000000-0000-0000-0000-000000000031', 'Patients who have already sustained a fragility fracture are considered at high enough risk to warrant treatment consideration even before or alongside DEXA results.', 3),
('c9000000-0000-0000-0000-000000000032', 'Osteopenia (T-score between -1.0 and -2.5) does not automatically require treatment; fracture risk should be estimated using tools such as FRAX that combine clinical risk factors with bone density.', 1),
('c9000000-0000-0000-0000-000000000032', 'FRAX incorporates factors such as age, sex, BMI, prior fracture, parental hip fracture, smoking, alcohol use, steroid use and bone density to estimate 10-year fracture probability.', 2),
('c9000000-0000-0000-0000-000000000032', 'Treatment thresholds are based on calculated absolute fracture risk, not on the T-score in isolation.', 3),
('c9000000-0000-0000-0000-000000000033', 'Oral bisphosphonates should be taken on an empty stomach with water, with the patient remaining upright for at least 30 minutes, to reduce oesophageal irritation and optimise absorption.', 1),
('c9000000-0000-0000-0000-000000000033', 'Bisphosphonates are contraindicated or require caution in patients with oesophageal strictures, achalasia, or an inability to remain upright.', 2),
('c9000000-0000-0000-0000-000000000033', 'Poor adherence to administration instructions is a common reason for reduced efficacy and increased gastrointestinal side effects with oral bisphosphonates.', 3),
('c9000000-0000-0000-0000-000000000034', 'Atypical femoral fractures are a recognised, though uncommon, complication of long-term bisphosphonate therapy, often preceded by prodromal thigh or groin pain.', 1),
('c9000000-0000-0000-0000-000000000034', $x$Characteristic radiographic features include a transverse or short oblique fracture with lateral cortical thickening ('beaking') in the subtrochanteric or diaphyseal femur.$x$, 2),
('c9000000-0000-0000-0000-000000000034', 'Bisphosphonate treatment duration should be periodically reviewed (e.g. after 3-5 years), balancing continued fracture prevention benefit against rare long-term risks such as atypical fracture and osteonecrosis of the jaw.', 3),
('c9000000-0000-0000-0000-000000000035', 'Long-term glucocorticoid therapy is a major risk factor for osteoporosis and fragility fracture, with risk rising with dose and duration.', 1),
('c9000000-0000-0000-0000-000000000035', 'Bone protection (typically a bisphosphonate) should be considered at the start of significant long-term steroid therapy, particularly in higher-risk patients, rather than delayed.', 2),
('c9000000-0000-0000-0000-000000000035', 'Calcium and vitamin D supplementation should be assessed and corrected as part of a bone protection strategy alongside specific anti-resorptive treatment where indicated.', 3),
('c9000000-0000-0000-0000-000000000036', 'Displaced intracapsular hip fractures are usually managed with arthroplasty due to the risk of avascular necrosis with internal fixation.', 1),
('c9000000-0000-0000-0000-000000000036', 'Early surgery (within about 36 hours) and orthogeriatric comanagement improve outcomes including mortality, pain and mobility after hip fracture.', 2),
('c9000000-0000-0000-0000-000000000036', 'All patients with a hip fracture should have secondary fracture prevention addressed (falls assessment, bone protection, vitamin D/calcium) once medically stable.', 3),
('c9000000-0000-0000-0000-000000000037', 'Denosumab is not renally excreted and can be used in patients with significant renal impairment where bisphosphonates are contraindicated or require caution.', 1),
('c9000000-0000-0000-0000-000000000037', 'Hypocalcaemia is a particular risk with denosumab, especially in renal impairment, and calcium/vitamin D status should be corrected and monitored.', 2),
('c9000000-0000-0000-0000-000000000037', 'Stopping denosumab without transitioning to another anti-resorptive agent is associated with rebound bone loss and an increased risk of multiple vertebral fractures.', 3),
('c9000000-0000-0000-0000-000000000038', $x$Denosumab's anti-resorptive effect is rapidly lost if doses are delayed or stopped, unlike the prolonged residual effect seen after stopping bisphosphonates.$x$, 1),
('c9000000-0000-0000-0000-000000000038', 'Discontinuing or significantly delaying denosumab is associated with rebound increased bone turnover and a risk of multiple vertebral fractures.', 2),
('c9000000-0000-0000-0000-000000000038', 'If denosumab is to be discontinued, transition to an alternative anti-resorptive agent (commonly a bisphosphonate) should be considered to mitigate rebound bone loss.', 3),
('c9000000-0000-0000-0000-000000000039', 'Osteomalacia results from inadequate bone mineralisation, typically due to vitamin D deficiency, and presents with bone pain, proximal myopathy and characteristic biochemistry (low calcium, low phosphate, raised alkaline phosphatase).', 1),
('c9000000-0000-0000-0000-000000000039', 'Osteoporosis is a disorder of reduced bone mass with normal mineralisation and typically normal calcium, phosphate and alkaline phosphatase; osteomalacia can coexist with, or mimic, osteoporosis on DEXA.', 2),
('c9000000-0000-0000-0000-000000000039', 'Treatment of osteomalacia (vitamin D and calcium replacement) differs from standard osteoporosis therapy and should be addressed as the primary underlying problem.', 3),
('c9000000-0000-0000-0000-000000000040', 'Fracture liaison services provide a systematic, cost-effective approach to secondary fracture prevention in patients presenting with fragility fractures.', 1),
('c9000000-0000-0000-0000-000000000040', 'A wrist fracture is a common early marker of osteoporosis and increased risk of future, more serious fractures such as hip fracture.', 2),
('c9000000-0000-0000-0000-000000000040', 'Secondary fracture prevention should combine bone health assessment/treatment with falls risk assessment, since both bone fragility and falls contribute to fracture risk.', 3),
('c9000000-0000-0000-0000-000000000041', 'STOPP criteria identify long-term proton pump inhibitor use at full dose beyond 8 weeks without a clear ongoing indication as potentially inappropriate prescribing.', 1),
('c9000000-0000-0000-0000-000000000041', 'Long-term PPI use is associated with risks including fracture, Clostridioides difficile infection, pneumonia, and vitamin B12/magnesium deficiency.', 2),
('c9000000-0000-0000-0000-000000000041', 'Regular medication review, particularly for drugs started during acute admissions, helps identify opportunities for safe deprescribing in older adults.', 3),
('c9000000-0000-0000-0000-000000000042', 'Anticholinergic burden accumulates when multiple drugs with anticholinergic properties are used together, even if each individual drug seems low risk.', 1),
('c9000000-0000-0000-0000-000000000042', 'Common anticholinergic side effects include confusion, dry mouth, blurred vision, urinary retention and constipation, and older adults are particularly susceptible to central effects such as delirium.', 2),
('c9000000-0000-0000-0000-000000000042', $x$Anticholinergic burden scales can help identify and quantify cumulative risk across a patient's medication list, guiding deprescribing decisions.$x$, 3),
('c9000000-0000-0000-0000-000000000043', $x$The 'triple whammy' combination of an ACE inhibitor (or ARB), a diuretic, and an NSAID significantly increases the risk of acute kidney injury by impairing renal autoregulation.$x$, 1),
('c9000000-0000-0000-0000-000000000043', 'NSAIDs should be avoided where possible in older patients, particularly those with chronic kidney disease or taking renin-angiotensin system blocking drugs and diuretics.', 2),
('c9000000-0000-0000-0000-000000000043', 'Any new acute kidney injury should prompt a careful medication review to identify potentially reversible pharmacological contributors.', 3),
('c9000000-0000-0000-0000-000000000044', 'Medication reconciliation compares what a patient was taking before admission with what they should take after discharge, identifying and resolving discrepancies.', 1),
('c9000000-0000-0000-0000-000000000044', 'Poor communication of medication changes at discharge is a major preventable cause of adverse drug events and hospital readmission in older adults.', 2),
('c9000000-0000-0000-0000-000000000044', 'Clear written and verbal communication with the patient, carers, and the GP is essential when multiple medication changes have occurred during an admission.', 3),
('c9000000-0000-0000-0000-000000000045', 'Digoxin is renally excreted, so acute or chronic kidney injury significantly increases the risk of toxicity; doses often require adjustment or the drug should be withheld.', 1),
('c9000000-0000-0000-0000-000000000045', 'Classic features of digoxin toxicity include gastrointestinal symptoms (nausea, anorexia, vomiting), visual disturbances (yellow-tinged vision, halos), and arrhythmias.', 2),
('c9000000-0000-0000-0000-000000000045', 'Renal function should be checked and digoxin levels considered whenever a patient on digoxin develops acute kidney injury or new symptoms suggestive of toxicity.', 3),
('c9000000-0000-0000-0000-000000000046', 'Macrolide antibiotics (e.g. clarithromycin, erythromycin) are well-recognised to interact with warfarin, increasing INR and bleeding risk via cytochrome P450 inhibition.', 1),
('c9000000-0000-0000-0000-000000000046', 'Any new medication started in a patient on warfarin should be checked for interactions, and more frequent INR monitoring arranged if an interacting drug is necessary.', 2),
('c9000000-0000-0000-0000-000000000046', 'A significantly supratherapeutic INR with bleeding requires urgent assessment and may need warfarin withholding and reversal depending on severity.', 3),
('c9000000-0000-0000-0000-000000000047', $x$Deprescribing decisions should consider overall prognosis, goals of care, and the time-to-benefit of preventive medications, which may exceed a patient's remaining life expectancy.$x$, 1),
('c9000000-0000-0000-0000-000000000047', 'Statins, along with other primary prevention medications, are commonly identified as appropriate to stop in patients with advanced frailty or limited life expectancy.', 2),
('c9000000-0000-0000-0000-000000000047', 'Any deprescribing decision should involve discussion with the patient (where possible) and family/carers, focusing on comfort and quality of life rather than long-term risk reduction.', 3),
('c9000000-0000-0000-0000-000000000048', 'Opioids reduce gut motility and commonly cause constipation; a stimulant laxative (rather than bulk-forming agents alone) is generally the most effective treatment.', 1),
('c9000000-0000-0000-0000-000000000048', 'Laxatives should ideally be co-prescribed prophylactically whenever a patient is started on regular opioid analgesia.', 2),
('c9000000-0000-0000-0000-000000000048', 'Overflow diarrhoea in a constipated patient on opioids should prompt assessment for faecal impaction rather than being mistaken for resolving symptoms.', 3),
('c9000000-0000-0000-0000-000000000049', 'Benzodiazepines are strongly associated with increased falls risk in older adults due to sedation, impaired balance and slowed reflexes, especially shortly after starting or dose changes.', 1),
('c9000000-0000-0000-0000-000000000049', 'Non-pharmacological approaches (sleep hygiene, addressing underlying causes such as grief) should be tried before considering sedative medication for insomnia in older adults.', 2),
('c9000000-0000-0000-0000-000000000049', 'Any new fall in an older patient should prompt review of recently started or changed medications as a potential contributing factor.', 3),
('c9000000-0000-0000-0000-000000000050', 'The combination of an anticoagulant with regular NSAID use is a recognised high-risk prescribing combination due to substantially increased bleeding risk, and NSAIDs should generally be avoided in patients on anticoagulation.', 1),
('c9000000-0000-0000-0000-000000000050', 'Structured tools such as STOPP/START criteria help systematically identify potentially inappropriate prescribing and missed beneficial treatments in older adults with polypharmacy.', 2),
('c9000000-0000-0000-0000-000000000050', 'New symptoms such as dizziness in a patient on multiple antihypertensive/rate-controlling agents should prompt review of cumulative drug burden, including checking for postural hypotension or bradycardia.', 3);
